:root{--bg:#0c1519;--pn:#14232a;--ink:#e6f1f2;--mu:#8fa7ad;--cy:#62e0f0;--am:#ffb454;--rd:#ff5a3a}
*{box-sizing:border-box}html,body{margin:0;height:100%;overflow:hidden;background:var(--bg);color:var(--ink);font:14px/1.35 Bahnschrift,"Segoe UI",system-ui,sans-serif}
canvas{display:block}
#menu,#pause,#end{position:fixed;inset:0;background:rgba(8,14,17,.96);overflow:auto;padding:22px 28px;z-index:5}
#pause,#end{display:none;background:rgba(8,14,17,.8);text-align:center;padding-top:22vh;font-size:20px}
h1{margin:0;font-size:32px;letter-spacing:.5px}h2{margin:16px 0 6px;font-size:15px;color:var(--cy);font-weight:600}
.sub{color:var(--mu);margin:2px 0 6px}
.row{display:flex;gap:8px;flex-wrap:wrap}
.c{background:var(--pn);color:var(--ink);border:1px solid #28404a;border-radius:6px;padding:7px 10px;text-align:left;cursor:pointer;font:inherit;min-width:120px}
.c b{display:block;font-weight:600}.c i{display:block;font-style:normal;color:var(--mu);font-size:12px}
.c.on{border-color:var(--am);background:#2a2518}.c:hover{border-color:var(--cy)}
#pts{float:right;color:var(--am)}#pts.bad{color:var(--rd)}
#go,.btn{margin-top:18px;background:var(--am);color:#1b1408;border:0;border-radius:6px;padding:11px 28px;font:600 16px inherit;font-family:inherit;cursor:pointer}
.btn.alt{background:var(--pn);color:var(--ink);margin-left:8px}
label{display:block;margin:6px 0;color:var(--mu)}select,input[type=range]{width:100%;background:var(--pn);color:var(--ink);border:1px solid #28404a;border-radius:6px;padding:5px}

#hud{position:fixed;inset:0;pointer-events:none;display:none}
#cx,#dfx .dret{position:absolute;left:50%;top:50%;width:19px;height:19px;transform:translate(-50%,-50%);pointer-events:none;color:var(--crosshair-color,#f8f8ed);filter:drop-shadow(0 1px 2px #000)}
#cx{transform:translate(-50%,-50%) scale(var(--crosshair-recoil-scale,1))}
#cx::before,#dfx .dret::before{content:"";position:absolute;inset:0;border:1px solid currentColor;border-radius:50%;transform:scale(var(--crosshair-size,1))}
#cx::after,#dfx .dret::after{content:"";position:absolute;left:50%;top:50%;width:3px;height:3px;background:currentColor;border-radius:50%;transform:translate(-50%,-50%) scale(var(--crosshair-size,1))}
#cx.t{color:var(--rd)}
.setup-actions{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:10px}
#practice-note:empty{display:none}
.practice-range #kst,.practice-range #hint{display:none}
.basic-training #rd{visibility:hidden}
#practice-reset[hidden]{display:none}
#training-coach{position:absolute;top:60px;left:clamp(12px,3vw,40px);width:min(305px,calc(100vw - 170px));padding:10px 14px;display:grid;gap:4px;border:1px solid #94b2bc66;border-left:3px solid #ffb454;border-radius:5px;background:#101a21ed;color:#fff}
#training-coach small{font:750 11px/1.25 system-ui;letter-spacing:.07em;text-transform:uppercase;color:#ffca80}
#training-coach strong{font:750 17px/1.1 system-ui}
#training-coach span{font:500 12px/1.4 system-ui;color:#dce7e8}
.sound-captions{position:absolute;left:50%;bottom:clamp(80px,17vh,144px);transform:translateX(-50%);width:max-content;max-width:72vw;display:grid;justify-items:center;gap:4px;text-align:center}
.sound-captions>div{padding:4px 10px;border:1px solid #92aebc75;border-radius:4px;background:#101a21ee;color:#fff;font:650 13px/1.35 system-ui}
.sound-captions span{margin-left:8px;color:#c3e9f2;font-weight:500}
.touch .sound-captions{bottom:max(40px,10vh);max-width:42vw}
#training-coach[hidden],.sound-captions[hidden]{display:none}
#p-set .audio-control,#pause .audio-control{display:grid;grid-template-columns:minmax(0,1fr) 5ch;gap:4px 8px;align-items:center}
.audio-control>span{grid-column:1/-1}
#p-set .audio-control input,#pause .audio-control input{margin:0;accent-color:var(--accent,#ffb454)}
.audio-control output{text-align:right;font-variant-numeric:tabular-nums}
.audio-checkbox>span{grid-column:1}
.audio-checkbox input{width:19px;height:19px;justify-self:end}
.aim-option output{min-width:3.5ch;text-align:right;color:var(--muted)}
[data-aim-option=color]{width:48px;height:32px;padding:2px;cursor:pointer}
.peer-controls{display:flex;align-items:center;gap:10px;justify-content:space-between}
.peer-controls .btn{flex:none}
.peer-list{padding:0;margin:8px 0;list-style:none}
.peer-list li+li{margin-top:5px}
#pause [hidden]{display:none!important}
[data-room-lock][aria-pressed=true]{border-color:var(--accent)}
#next-loadout-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(160px,100%),1fr));gap:6px;margin-top:10px}
#next-loadout-list button{min-width:0;text-align:left}
#next-loadout-list button span{display:block;margin-top:3px;font-size:.78em;color:var(--soft)}
#next-loadout-list button[data-active]::after{content:"Active";display:block;margin-top:3px;font-size:.72em;color:#81e4b9}
#next-loadout-list button[aria-pressed=true]{border-color:var(--accent);background:var(--raised)}
#next-loadout-status{margin:9px 0 0;color:var(--soft);font-size:.9em}
.record-stats{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(125px,100%),1fr));gap:8px;margin:18px 0 0}
.record-stats div{padding:10px 14px;border:1px solid var(--line);border-radius:5px;background:var(--surface)}
.record-stats dt,.record-table small,.record-table time,.record-note,.record-empty{color:var(--soft)}
.record-stats dd{margin:4px 0 0;font-size:1.35rem;font-weight:700;font-variant-numeric:tabular-nums}
.record-note{font-size:.84em;margin:12px 0}
.record-scroll{overflow-x:auto}
.record-table{width:100%;border-collapse:collapse;font-size:.9em;text-align:left;font-variant-numeric:tabular-nums}
.record-table th,.record-table td{padding:10px 12px;border-bottom:1px solid var(--line);white-space:nowrap}
.record-table small,.record-table time{display:block;margin-top:4px;font-size:.83em}
.party-actions{display:flex;flex-wrap:wrap;gap:8px}
#hm{position:absolute;left:50%;top:50%;width:30px;height:30px;margin:-15px;opacity:0;transition:opacity .25s;background:linear-gradient(45deg,transparent 45%,#fff 45% 55%,transparent 55%),linear-gradient(-45deg,transparent 45%,#fff 45% 55%,transparent 55%)}
#hm.on{opacity:1;transition:none}#hm.hd{filter:drop-shadow(0 0 3px var(--rd))}
#dm{position:absolute;inset:0;box-shadow:inset 0 0 120px 30px var(--rd);opacity:0}
#bars{position:absolute;left:24px;bottom:24px;width:240px}.bar{height:10px;background:#0006;margin-top:5px;border:1px solid #fff3}.bar div{height:100%}
#sh{background:var(--cy)}#hp{background:#7bd86b}
#am{position:absolute;right:28px;bottom:22px;text-align:right;font-size:36px}#am small{display:block;font-size:14px;color:var(--mu)}
#ob{position:absolute;top:16px;width:100%;text-align:center;font-size:18px;text-shadow:0 1px 4px #000}
/* polish */
.how{display:flex;gap:16px;flex-wrap:wrap;color:var(--mu);margin-bottom:10px}kbd{background:#1b2f37;border:1px solid #3b5963;border-bottom-width:3px;border-radius:5px;padding:1px 6px;margin-right:3px;color:var(--ink);font:inherit;font-size:12px}
#hud:before{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at center,transparent 55%,#0007 100%)}
.ft{position:absolute;font-weight:700;font-size:20px;text-shadow:0 2px 4px #000;pointer-events:none;animation:fl .8s ease-out forwards}
@keyframes fl{to{transform:translateY(-60px) scale(1.3);opacity:0}}
#hint{position:absolute;bottom:80px;width:100%;text-align:center;color:#fff;text-shadow:0 1px 4px #000;opacity:0;transition:opacity 1.2s}
.bar{border-radius:5px;overflow:hidden;height:12px}#sh{box-shadow:0 0 10px var(--cy)}#am{text-shadow:0 2px 6px #000}
#end,#pause{backdrop-filter:blur(6px)}#end small{display:block;margin-top:10px;line-height:1.7;color:var(--mu);font-size:16px}
#rank{color:var(--am);margin:0 0 8px;font-size:16px}
#rd{position:absolute;left:20px;top:20px;border-radius:50%;box-shadow:0 0 14px #0008}
#kf{position:absolute;right:20px;top:20px;text-align:right;text-shadow:0 1px 4px #000;line-height:1.6}
#ks{position:absolute;bottom:118px;width:100%;text-align:center;color:var(--cy);font-size:18px;text-shadow:0 1px 4px #000}
#di{position:absolute;left:50%;top:50%;width:280px;height:280px;margin:-140px;border-radius:50%;border-top:10px solid rgba(255,70,50,.95);opacity:0}
@keyframes di{0%{opacity:1}100%{opacity:0}}
.c.lk{opacity:.4;cursor:not-allowed;filter:grayscale(1)}.c.lk:hover{transform:none;border-color:#28404a}
.btn.sm{margin:4px 0;padding:5px 12px;font-size:13px}#prest{margin-left:10px;vertical-align:middle}
summary{cursor:pointer;color:var(--cy);font-weight:600;margin-top:16px}
/* ===== main menu redesign ===== */
body{font-family:Rajdhani,Bahnschrift,"Segoe UI",system-ui,sans-serif;font-size:16px;font-weight:500}
h1,h2,h3,.big,#nav button,#code{font-family:Teko,Impact,sans-serif;font-weight:600;letter-spacing:1.5px;text-transform:uppercase}
.c{min-width:200px;padding:10px 14px}.c b{font-size:17px}
.big{display:inline-block;margin:10px 10px 0 0;padding:6px 34px;font-size:26px;background:var(--am);color:#1b1408;border:0;cursor:pointer;clip-path:polygon(14px 0,100% 0,calc(100% - 14px) 100%,0 100%);transition:.1s}.big:hover{filter:brightness(1.12);transform:translateY(-2px)}.big.alt{background:#2a3d46;color:var(--ink)}
input[type=text]{width:100%;background:var(--pn);color:var(--ink);border:1px solid #28404a;border-radius:4px;padding:7px;font:inherit;text-transform:uppercase}#nm{text-transform:none}

#dev{display:none;position:absolute;inset:0;background:#000b;align-items:center;justify-content:center;z-index:10}
.card{background:#0f1c23;border:1px solid #3b5963;padding:24px 34px;min-width:360px;text-align:left;clip-path:polygon(0 0,calc(100% - 24px) 0,100% 24px,100% 100%,24px 100%,0 calc(100% - 24px))}.card h2{margin:0 0 6px;font-size:38px}.card .big{display:block;width:100%;margin:10px 0 0}
#pause,#end{padding-top:12vh}#pause .card,#end .card{display:inline-block}#et{font-family:Teko,sans-serif;font-size:44px;text-transform:uppercase}
body.net #again{display:none}
/* popups + killstreak panel */
#kst{position:absolute;right:18px;top:50%;transform:translateY(-50%);width:176px;text-shadow:0 1px 4px #000}#kst small{display:block;color:var(--mu);letter-spacing:2px;font-size:12px;margin-bottom:6px;text-align:right}
.kt{display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;padding:6px 10px;background:#0a141a99;border-right:4px solid #3b5963;color:var(--mu);transition:.2s}.kt b{font:600 20px Teko,sans-serif;letter-spacing:1px;text-transform:uppercase}.kt i{font-style:normal;font-size:13px}
.kt.used{opacity:.45}.kt.rdy{color:#fff;border-right-color:var(--am);background:#3a2a0ccc;animation:glow 1s ease-in-out infinite alternate}
@keyframes glow{from{box-shadow:0 0 6px #ffb45466}to{box-shadow:0 0 26px 4px #ffb454cc}}
/* ===== mobile, no-select, no-zoom ===== */
*{-webkit-user-select:none;user-select:none;-webkit-touch-callout:none;-webkit-tap-highlight-color:transparent}input{-webkit-user-select:text;user-select:text}
html,body{touch-action:pan-x pan-y;overscroll-behavior:none}canvas{touch-action:none}
#tc{display:none}body.touch #tc{display:block}#tc *{pointer-events:auto}
#stick{position:absolute;left:24px;bottom:24px;width:130px;height:130px;border-radius:50%;background:#0b161c80;border:2px solid #62e0f066;touch-action:none}
#stick i{position:absolute;left:35px;top:35px;width:60px;height:60px;border-radius:50%;background:#62e0f0aa}
.tb{position:absolute;width:58px;height:58px;border-radius:50%;background:#0b161cb0;border:2px solid #62e0f0aa;color:#fff;font:600 12px Rajdhani,sans-serif;letter-spacing:.5px;display:flex;align-items:center;justify-content:center;touch-action:none}.tb.on{background:#ffb454cc;color:#1b1408}
body.touch #bars{bottom:auto;top:178px;left:20px;width:150px}body.touch #am{left:50%;right:auto;transform:translateX(-50%);bottom:10px;text-align:center;font-size:30px}
body.touch #kf{top:62px;right:12px}body.touch #kst{width:128px;right:8px}body.touch #ks{bottom:70px}body.touch #hint{bottom:46px;font-size:13px}
@media (max-width:900px),(max-height:520px){
 #pause,#end{padding-top:3vh;overflow:auto}.card{min-width:0;width:min(92vw,380px);max-height:94vh;overflow:auto;padding:16px 22px}}

/* ===== match end: freeze, victory / defeat, leaderboard, podium ===== */
#fin{position:fixed;inset:0;z-index:6;display:none;pointer-events:none;color:var(--ink)}#fin>*,#fpod>*{position:absolute}
#fbl{inset:0;background:rgba(6,12,16,.42);backdrop-filter:blur(12px) saturate(.75);-webkit-backdrop-filter:blur(12px) saturate(.75);opacity:0;transition:opacity .7s}
#fin.s-vic #fbl,#fin.s-board #fbl{opacity:1}
#fvt{left:0;right:0;top:42%;transform:translateY(-50%);text-align:center;opacity:0;transition:opacity .45s,transform .45s}
#fin.s-vic #fvt{opacity:1;animation:vpop .75s cubic-bezier(.2,1.5,.35,1)}#fin.s-board #fvt{transform:translateY(-50%) scale(1.08)}
@keyframes vpop{from{transform:translateY(-50%) scale(3);opacity:0;filter:blur(14px)}}
#fvt b{display:block;font:700 clamp(84px,20vw,240px)/.88 Teko,Impact,sans-serif;letter-spacing:.05em;text-transform:uppercase;color:#ffd24a;text-shadow:0 0 44px #ffb45488,0 7px 0 #7a5410}
#fin.lose #fvt b{color:#ff5a3a;text-shadow:0 0 44px #ff5a3a77,0 7px 0 #6a1d10}
#fvt span{display:block;margin-top:10px;font:600 clamp(16px,2.4vw,30px) Rajdhani,sans-serif;letter-spacing:.18em;color:#cfe0e3;text-shadow:0 2px 6px #000}
#fvt:before{content:"";position:absolute;left:0;right:0;top:50%;height:62%;transform:translateY(-50%) scaleX(0);background:linear-gradient(90deg,transparent,#ffb45424 18%,#ffb45424 82%,transparent);z-index:-1;transition:transform .7s .1s}
#fin.lose #fvt:before{background:linear-gradient(90deg,transparent,#ff5a3a22 18%,#ff5a3a22 82%,transparent)}#fin.s-vic #fvt:before{transform:translateY(-50%) scaleX(1)}
#fbd{left:50%;top:50%;transform:translate(-50%,-47%);width:min(740px,94vw);max-height:90vh;overflow:auto;padding:22px 30px 26px;background:#0a141aee;border:1px solid #28404a;opacity:0;pointer-events:none;transition:opacity .5s .2s,transform .5s .2s;clip-path:polygon(0 0,calc(100% - 28px) 0,100% 28px,100% 100%,28px 100%,0 calc(100% - 28px))}
#fin.s-board #fbd{opacity:1;transform:translate(-50%,-50%);pointer-events:auto}
#fbd h2{margin:0;font-size:56px;line-height:1;color:#ffd24a}#fin.lose #fbd h2{color:#ff5a3a}
#fbd table{width:100%;border-collapse:collapse;margin:10px 0 6px}#fbd th{text-align:left;color:var(--mu);font-weight:600;padding:4px 10px}
#fbd td{padding:6px 10px;border-top:1px solid #28404a;font-size:20px}#fbd td:first-child{width:46px;border-left:4px solid transparent;color:var(--mu)}
#fbd th:nth-child(n+3),#fbd td:nth-child(n+3){text-align:right;width:84px}#fbd tr.me td{background:#ffb45420;color:var(--am)}
.fs{margin:6px 0;color:var(--mu);font-size:16px;line-height:1.5}#fcont{margin-top:14px}
#fskip-board{margin:14px 0 0 8px}
#fskip-board,#fskip-pod{visibility:hidden}
#fin.s-board:not(.blk) #fskip-board,#fin.s-pod:not(.blk) #fskip-pod{visibility:visible}
#fskip-pod{left:50%;bottom:calc(90px + env(safe-area-inset-bottom));transform:translateX(-50%);pointer-events:auto}
#fpod{inset:0;opacity:0;transition:opacity .45s}#fin.s-pod #fpod{opacity:1}#fnm{inset:0}
#fcd{top:22px;left:0;right:0;margin:0;text-align:center;font:600 22px Rajdhani,sans-serif;letter-spacing:.12em;color:#cfe0e3;text-shadow:0 2px 6px #000}
.pl{position:absolute;transform:translate(-50%,-100%);text-align:center;white-space:nowrap;text-shadow:0 2px 6px #000}.pl b{display:block;font:600 26px Teko,sans-serif;letter-spacing:1px;line-height:1}.pl i{font-style:normal;color:var(--mu);font-size:15px}.pl.me b{color:var(--am)}
#fem{left:0;right:0;bottom:26px;display:flex;justify-content:center;gap:10px}
#fem button{pointer-events:auto;cursor:pointer;background:#0b161ccc;color:#fff;border:1px solid #62e0f0aa;padding:6px 22px 6px 12px;font:600 24px Teko,sans-serif;letter-spacing:1px;clip-path:polygon(12px 0,100% 0,calc(100% - 12px) 100%,0 100%);transition:.1s}
#fem button:hover{background:#ffb454;color:#1b1408;border-color:#ffb454}#fem kbd{margin-right:8px}body.touch #fem kbd{display:none}
#ffd{inset:0;background:#000;opacity:0;transition:opacity .5s}#fin.blk #ffd{opacity:1}
@media (max-width:900px),(max-height:520px){#fbd{padding:12px 14px 16px}#fbd h2{font-size:34px}#fbd td{font-size:16px;padding:4px 8px}.fs{font-size:13px}#fem{bottom:12px;gap:6px}#fem button{font-size:20px;padding:4px 14px 4px 8px}.pl b{font-size:20px}}
@media (prefers-reduced-motion:reduce){#fin.s-vic #fvt{animation:none}}

/* ===== zombies HUD ===== */
#zh{display:none;position:absolute;left:24px;bottom:84px}
#zr{font:700 96px/.9 Teko,Impact,sans-serif;color:#b3261e;text-shadow:0 0 18px #ff2a2a66,0 3px 0 #2a0a08;letter-spacing:2px}
#zpt{font:600 36px Teko,sans-serif;color:#ffd24a;text-shadow:0 2px 4px #000;letter-spacing:1px}
#zpk{display:flex;gap:5px;margin-top:6px}#zpk i{display:block;width:26px;height:26px;border:1px solid #0008;border-radius:4px;font:700 17px/26px Teko,sans-serif;font-style:normal;text-align:center;color:#fff;text-shadow:0 1px 2px #000}
#zp{position:absolute;left:0;right:0;bottom:150px;text-align:center;font:600 24px Rajdhani,sans-serif;color:#fff;text-shadow:0 2px 6px #000}#zp.bad{color:#ff8a6a}
body.touch #zh{bottom:auto;top:230px}body.touch #zr{font-size:60px}body.touch #zp{bottom:100px}
body.zom #kst{display:none}

#zt{margin-top:8px;font:600 18px Rajdhani,sans-serif;color:#cfe0e3;text-shadow:0 1px 3px #000;line-height:1.25}
#home{position:fixed;inset:0;z-index:5;display:none}

button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #62e0f0;outline-offset:2px}

#scope{position:fixed;inset:0;z-index:12;display:none;pointer-events:none;background:radial-gradient(circle at 50% 50%,transparent 0,transparent 31%,#000 32.5%);}
#flash{position:fixed;inset:0;z-index:30;background:#fff;opacity:0;pointer-events:none}
#nvo{position:fixed;inset:0;z-index:11;display:none;pointer-events:none;background:radial-gradient(circle,transparent 45%,#001a00dd 100%)}
#sbd{position:fixed;left:50%;top:12%;transform:translateX(-50%);z-index:20;display:none;min-width:360px;background:#08121cdd;border:1px solid #62e0f066;border-radius:10px;padding:14px 22px;color:#e8f4f8;font-family:Rajdhani,sans-serif}
#sbd h3{margin:0 0 8px;font-family:Teko,sans-serif;font-size:28px;letter-spacing:2px}#sbd table{width:100%;border-collapse:collapse}#sbd td{padding:3px 8px}#sbd tr.me{color:#62e0f0;font-weight:700}
#mapv{position:fixed;left:50%;top:50%;transform:translate(-50%,-50%);z-index:20;display:none;background:#08121cee;border:1px solid #62e0f066;border-radius:10px;padding:10px;text-align:center;color:#9bb}
#mapv canvas{width:min(80vh,92vw);height:min(80vh,92vw)}
#osk{position:fixed;left:50%;bottom:4%;transform:translateX(-50%);z-index:60;display:none;background:#08121cf0;border:1px solid #62e0f088;border-radius:12px;padding:10px}
#osk .r{display:flex;gap:6px;margin:6px 0;justify-content:center}#osk button{min-width:46px;height:46px;font-size:20px;border-radius:8px;border:1px solid #62e0f055;background:#12303a;color:#fff}

#vrsplash{position:fixed;inset:0;z-index:99;background:#061018f2;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;color:#62e0f0;font-family:Teko,sans-serif;cursor:pointer}
#vrsplash b{font-size:96px;letter-spacing:8px}#vrsplash span{font-size:26px;color:#9bb;font-family:Rajdhani,sans-serif}

/* Loadout and model picker */
#p-load{padding:0;overflow:hidden;clip-path:none;background:#151a1b;border-color:#41433b;--arsenal-ink:#f4eddd;--arsenal-muted:#b7b9ac;--arsenal-gold:#eec681;--arsenal-line:#403f36;--arsenal-surface:#252925;color:var(--arsenal-ink)}
#p-load.on{display:flex;flex-direction:column}
#ld{height:100%;min-height:0;overflow:auto;scrollbar-gutter:stable}
.arsenal{padding:24px clamp(15px,2.5vw,38px) 30px}
.arsenal-header{display:flex;justify-content:space-between;gap:16px;align-items:end;padding-bottom:16px;border-bottom:1px solid var(--arsenal-line)}
#p-load .arsenal-header h2{margin:0 0 4px;font-size:clamp(36px,4.1vw,57px);line-height:1;color:var(--arsenal-ink);letter-spacing:.07em}
.lo-tabs{display:flex;gap:5px;flex-wrap:wrap}
.arsenal button{font:inherit;cursor:pointer}
.arsenal .lt{background:#1d2220;border:1px solid var(--arsenal-line);color:var(--arsenal-muted);min-width:35px;min-height:33px;padding:3px 6px;font-family:ui-monospace,monospace;font-size:12px}
.arsenal .lt.on{background:var(--arsenal-gold);border-color:var(--arsenal-gold);color:#211b14}
.arsenal .lt:hover,.arsenal-view button:hover{border-color:var(--arsenal-gold);color:var(--arsenal-ink)}
.arsenal .lt.on:hover{color:#211b14}
.arsenal-budget{display:grid;grid-template-columns:auto auto;align-items:baseline;gap:4px 12px;flex:none}
.arsenal-budget span{font-size:13px;color:var(--arsenal-muted)}
.arsenal-budget strong{font:600 28px/1 Teko,Impact,sans-serif;color:var(--arsenal-gold)}
.arsenal-budget small{font-size:.64em;color:var(--arsenal-muted)}
.arsenal-budget strong.bad{color:#ff9c79;font-size:19px;max-width:120px;text-align:right}
.arsenal-budget meter{width:100%;height:5px;grid-column:1/-1;margin-top:2px;appearance:none}
.arsenal-budget meter::-webkit-meter-bar{height:5px;background:#414034;border:0;border-radius:0}
.arsenal-budget meter::-webkit-meter-optimum-value{background:var(--arsenal-gold)}
.arsenal-budget meter::-moz-meter-bar{background:var(--arsenal-gold)}
.arsenal-slots{display:flex;gap:5px;flex-wrap:wrap;margin:12px 0 17px}
.arsenal-slots .ls{display:inline-grid;gap:1px;text-align:left;background:#202523;color:var(--arsenal-ink);border:1px solid #3a3c34;padding:6px 10px;min-height:41px}
.arsenal-slots .ls span{line-height:1;font-size:14px;font-weight:700}
.arsenal-slots .ls b{font-size:11px;line-height:1.1;font-weight:600;color:var(--arsenal-muted)}
.arsenal-slots .ls.sel{border-color:#cead73;background:#352f24}
.arsenal-slots .ls:hover{border-color:var(--arsenal-gold)}
.arsenal-feature{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(205px,1fr);border:1px solid #4e4b3b;background:#242823}
.arsenal-stage{display:flex;flex-direction:column;justify-content:center;min-width:0;padding:6px;
 background-color:#1a201f;background-image:radial-gradient(ellipse at 47% 53%,#6b67564d,transparent 67%),linear-gradient(#8b9b860d 1px,transparent 1px),linear-gradient(90deg,#8b9b860d 1px,transparent 1px);background-size:100% 100%,26px 26px,26px 26px}
.arsenal-stage canvas{width:100%;height:auto;aspect-ratio:640/300;object-fit:contain;touch-action:none;cursor:grab;background-size:contain;background-repeat:no-repeat;background-position:center}
.arsenal-stage canvas:active{cursor:grabbing}
.arsenal-view{display:flex;justify-content:center;gap:5px;margin:0 0 7px}
.arsenal-view button,.arsenal-actions button{background:#212522;border:1px solid #67624f;color:var(--arsenal-ink);padding:4px 13px;line-height:1.15;font-size:13px;font-weight:700;min-height:30px}
.arsenal-view button[aria-pressed=true],.arsenal-actions button:first-child{background:var(--arsenal-gold);color:#231b12;border-color:var(--arsenal-gold)}
.arsenal-view [data-rotate]{font:700 24px/.8 Teko,sans-serif;padding:3px 9px}
.arsenal-details{border-left:1px solid #4e4b3b;padding:17px clamp(12px,1.8vw,25px);display:grid;align-content:center}
.arsenal-class{font:600 11px/1.3 ui-monospace,monospace;letter-spacing:.1em;color:var(--arsenal-gold)}
#p-load .arsenal-details h3{color:var(--arsenal-ink);font-size:clamp(31px,4vw,53px);line-height:1;letter-spacing:.045em;margin:5px 0 2px}
.arsenal-details p{font-size:14px;margin:2px 0 12px;color:var(--arsenal-muted);line-height:1.3}
.arsenal-stats{display:grid;grid-template-columns:repeat(3,1fr);border-block:1px solid #4e4b3b;padding:7px 0;margin-bottom:12px;gap:6px}
.arsenal-stats div{display:grid}
.arsenal-stats span{color:var(--arsenal-muted);font-weight:600;font-size:12px;white-space:nowrap}
.arsenal-stats b{font:600 22px/1.25 Teko,Impact,sans-serif;color:var(--arsenal-ink)}
.arsenal-stats small{font-size:12px;color:var(--arsenal-muted)}
.arsenal-actions{display:flex;gap:7px;flex-wrap:wrap}
.arsenal-actions .arsenal-remove{min-width:0;background:#262a23}
.arsenal-actions button:hover{filter:brightness(1.16)}
.arsenal-catalog,.arsenal-attachments{margin-top:19px}
#p-load .arsenal-catalog h3,#p-load .arsenal-attachments h3{font-size:25px;line-height:1;color:var(--arsenal-ink);margin:0 0 8px;letter-spacing:.075em}
.arsenal-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,145px),1fr));gap:8px}
.arsenal .arsenal-card{min-width:0;margin:0;display:grid;position:relative;gap:3px;align-content:start;padding:4px 8px 7px;border:1px solid #45483d;border-radius:2px;background:linear-gradient(145deg,#33382e,#1c2421);opacity:1;color:var(--arsenal-ink);transform:none;box-shadow:none}
.arsenal .arsenal-card.on{border-color:var(--arsenal-gold);background:linear-gradient(145deg,#514538,#282a22)}
.arsenal .arsenal-card:hover{transform:none;border-color:#ecce93;box-shadow:none}
.arsenal .arsenal-card.lk{filter:none;cursor:pointer}
.arsenal .arsenal-card.lk .arsenal-model{filter:saturate(.6) brightness(.83)}
.arsenal-model{display:block;aspect-ratio:640/300;min-height:42px}
.arsenal-model img{display:block;width:100%;height:100%;object-fit:contain;filter:brightness(1.22) drop-shadow(0 4px 4px #10131399)}
.arsenal-model img:not([src]){visibility:hidden}
.arsenal-card-text{display:grid;line-height:1.05}
.arsenal .arsenal-card-text b{font-size:17px;font-weight:700}
.arsenal-card-text small{font:600 10px/1.25 ui-monospace,monospace;color:var(--arsenal-muted);margin-top:4px;letter-spacing:.025em}
.arsenal-equipped{position:absolute;right:5px;top:5px;padding:2px 5px;border:1px solid #bd9b60;background:#282619;color:#f2d299;font:600 9px/1.1 ui-monospace,monospace}
.arsenal-attachments h3 small{letter-spacing:0;font:600 13px/1 ui-monospace,monospace;color:var(--arsenal-muted)}
.arsenal .row button{min-width:120px;flex:1 1 120px;max-width:245px;border-radius:2px}
.arsenal-equipment{background:#202523;border:1px solid var(--arsenal-line);padding:18px}
.arsenal-equipment h3{font-size:34px;color:var(--arsenal-ink);margin:0 0 6px}
.arsenal-equipment h4{color:var(--arsenal-gold);margin:10px 0 5px}
.dimg.meleei{height:120px;background:radial-gradient(ellipse at center,#5d63493d,transparent 70%)}
.dd{color:#b7b9ac;margin:4px 0 10px;font-size:15px}.dd kbd,.how kbd{background:#1c2f38;border:1px solid #3a5560;border-radius:3px;padding:0 5px;color:#fff}
.sb{display:flex;align-items:center;gap:8px;margin:3px 0;font-size:12px;color:var(--arsenal-muted)}.sb span{width:76px;text-transform:uppercase;letter-spacing:1px}.sb i{flex:1;height:6px;background:#39392d}.sb em{display:block;height:100%;background:var(--arsenal-gold)}
@media(max-width:1180px) and (min-width:901px){.arsenal{padding-inline:16px}.arsenal-feature{grid-template-columns:minmax(0,1.25fr) minmax(170px,1fr)}.arsenal-details{padding:12px}}
@media(max-width:620px){
 .arsenal{padding:14px 11px 20px}
 .arsenal-feature{grid-template-columns:1fr}
 .arsenal-stage canvas{max-height:155px}
 .arsenal-details{border-left:0;border-top:1px solid #4e4b3b;padding:12px}
 .arsenal-header{align-items:start}
 .arsenal-slots{gap:4px;margin-bottom:11px}
 .arsenal-slots .ls{flex:1 0 auto;min-height:36px;padding:5px 7px}
 .arsenal-slots .ls span{font-size:12px}
 .arsenal-slots .ls b{font-size:10px}
 .arsenal-budget{gap:3px 6px}
 .arsenal-budget span{font-size:11px}
 .arsenal-budget strong{font-size:24px}
 .arsenal-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}

/* ---------- customize weapon (camo screen) ---------- */
.big.cust{width:100%;margin:2px 0 6px;background:linear-gradient(180deg,#d4571f,#8f2e0d);border-color:#ff9a5a}
.cu{display:flex;flex-direction:column;min-height:100%;background:radial-gradient(ellipse at 50% 20%,#0f2330 0,#050a10 70%);padding:10px 18px 14px;gap:8px}
.cu-top{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.cu-back{width:30px;height:30px;border:1px solid #3a5560;background:#101c24;color:#fff;font-size:20px;cursor:pointer}
.cu-crumb small{display:block;color:#8fa7ad;font-size:10px;letter-spacing:1.4px}.cu-crumb h2{margin:0;font:700 34px Teko,Bahnschrift,sans-serif;letter-spacing:2px;line-height:1}
.cu-tabs{margin:0 auto;display:flex;gap:26px}.cu-tabs button{background:none;border:0;border-bottom:3px solid transparent;color:#8fa7ad;font:700 14px inherit;font-family:inherit;letter-spacing:2px;padding:6px 2px;cursor:pointer}.cu-tabs button.on{color:#fff;border-bottom-color:var(--cy)}
.cu-wsel{display:flex;align-items:center;gap:8px;color:#fff;font-weight:700;letter-spacing:1px}.cu-wsel i{font-style:normal;color:var(--cy);font-size:12px}.cu-wsel button{background:#101c24;border:1px solid #3a5560;color:#fff;width:28px;height:28px;cursor:pointer}
.cu-main{display:grid;grid-template-columns:1fr 290px;gap:10px;min-height:260px;flex:1}
.cu-stage{position:relative;display:flex;align-items:center;justify-content:center;min-height:240px}.cu-stage img{width:100%;max-height:340px;object-fit:contain;filter:drop-shadow(0 12px 18px #000a)}.cu-stage b{position:absolute;left:8px;bottom:4px;font-size:11px;letter-spacing:2px;color:#8fa7ad}
.cu-info h3{margin:6px 0 8px;font:700 38px Teko,Bahnschrift,sans-serif;letter-spacing:2px}.cu-info .st{margin:0 0 4px;font-size:12px;letter-spacing:2px}.cu-info .st.ok{color:#5ae08a}.cu-info .st.lk{color:#ffb454}.cu-info .rq{color:#9db3b9;margin:4px 0 10px;font-size:14px}
.pg{position:relative;height:16px;background:#14222b;border:1px solid #2a424c}.pg i{position:absolute;left:0;top:0;bottom:0;background:var(--cy);display:block}.pg span{position:absolute;right:6px;top:-1px;font-size:12px;color:#fff}
.cu-bot{display:flex;flex-direction:column;gap:6px}.cu-modes{display:flex;gap:18px;border-bottom:1px solid #1d3340;padding-bottom:4px}.cu-modes button{background:none;border:0;border-bottom:2px solid transparent;color:#8fa7ad;font:700 12px inherit;font-family:inherit;letter-spacing:1.6px;padding:4px 2px;cursor:pointer}.cu-modes button.on{color:#fff;border-bottom-color:var(--cy)}
.cu-groups{display:flex;gap:26px;flex-wrap:wrap;align-items:flex-start}.cg h4{margin:0 0 4px;font-size:11px;letter-spacing:2px;color:#8fa7ad}.cr{display:flex;gap:5px;flex-wrap:wrap}
.ct{position:relative;width:62px;height:62px;border:1px solid #2a424c;background:#0b1319;padding:3px;cursor:pointer}.ct.sel{border-color:#ff7a2a;box-shadow:0 0 12px #ff7a2a88}.ct .sw{display:block;width:100%;height:100%;background-color:var(--c,#222);background-size:cover;background-position:center}
.ct.lk .sw{filter:brightness(.55) saturate(.6)}.ct u{position:absolute;left:3px;top:2px;text-decoration:none;font-size:11px}.ct em{position:absolute;left:0;right:0;bottom:0;background:#000b;color:#5ae08a;font:700 8px inherit;font-family:inherit;text-align:center;font-style:normal;letter-spacing:.5px}.ct em.tk{bottom:10px;color:#ffd24a}
.ct.an .sw{background:conic-gradient(from 0deg,var(--c),#fff4,var(--c),#0006,var(--c));animation:cuspin 6s linear infinite}@keyframes cuspin{to{filter:hue-rotate(360deg)}}
.cu-btns{display:flex;gap:10px;margin-top:2px}.cu-btns button{background:#0f1d26;border:1px solid #3a5560;color:#fff;padding:8px 14px;font:700 12px inherit;font-family:inherit;letter-spacing:1.4px;cursor:pointer}.cu-btns button:hover{border-color:var(--cy)}.cu-trk{margin:2px 0 0;color:#ffd24a;font-size:12px}
.cu-wlist{grid-column:1/-1;display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:6px;align-content:start}.cu-wlist button{background:#0e1a20;border:1px solid #243b45;color:#fff;padding:10px;text-align:left;cursor:pointer}.cu-wlist button.on{border-color:#ff7a2a}.cu-wlist i{display:block;font-style:normal;color:var(--cy);font-size:11px}
@media(max-width:800px){.cu-main{grid-template-columns:1fr}}

.dimg.meleei img{filter:none;max-height:100%;max-width:100%;width:100%;height:100%;object-fit:contain}

/* ---------- killstreak screen ---------- */
.skp{min-height:100%;background:radial-gradient(ellipse at 30% 0,#101c26 0,#05090e 70%);padding:10px 18px 14px;display:flex;flex-direction:column;gap:10px}
.sk-top{display:flex;align-items:center;gap:14px;flex-wrap:wrap}.sk-top h2{margin:0;font:700 44px Teko,Bahnschrift,sans-serif;letter-spacing:3px;background:linear-gradient(180deg,#fff,#9aa6ae);-webkit-background-clip:text;background-clip:text;color:transparent}
.sk-cats{display:flex;gap:4px;margin-left:auto;flex-wrap:wrap}.sk-cats button{background:#0e1a20;border:1px solid #2a424c;color:#9db3b9;min-width:30px;height:28px;font:700 12px inherit;font-family:inherit;cursor:pointer}.sk-cats button.on{background:#16323d;color:#fff;border-color:var(--cy)}
.sk-main{display:grid;grid-template-columns:minmax(360px,1.25fr) minmax(260px,1fr);gap:18px}
.sk-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(116px,1fr));gap:6px;align-content:start;max-height:62vh;overflow:auto;padding-right:4px}
.sk{position:relative;background:#0c151c;border:1px solid #1f323c;color:#fff;text-align:left;cursor:pointer;height:116px;padding:6px;overflow:hidden}.sk:hover{border-color:var(--cy)}
.sk.sel{border-color:#ff7a2a;box-shadow:0 0 0 1px #ff7a2a,0 0 14px #ff7a2a66;background:linear-gradient(180deg,#1b2630,#0c151c)}.sk.eq{background:#142029}
.sk .ski{display:block;height:68px}.sk .ski img{width:100%;height:100%;object-fit:contain;display:block;filter:drop-shadow(0 4px 6px #000a)}
.sk>b{position:absolute;left:6px;bottom:4px;right:4px;font:600 13px Rajdhani,sans-serif;letter-spacing:.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sk .skc{position:absolute;left:6px;top:4px;color:#ff7a2a;font:700 12px inherit;font-family:inherit}.sk u{position:absolute;right:6px;top:4px;text-decoration:none;font-size:12px}.sk.lk .ski img{filter:brightness(.35) grayscale(1)}.sk small{position:absolute;right:6px;bottom:20px;font-size:10px;color:#ffb454}
.sk-info h3{display:inline-block;margin:0 0 6px;background:#e8eef2;color:#0a1218;padding:2px 10px;font:700 28px Teko,Bahnschrift,sans-serif;letter-spacing:1px}.sk-d{margin:4px 0;color:#d4dde2}.sk-m{margin:2px 0 6px;color:#ffb454;font-size:12px;letter-spacing:1px}
.sk-big{height:230px;background:radial-gradient(ellipse at 50% 55%,#1d3441 0,transparent 70%)}.sk-big img{width:100%;height:100%;object-fit:contain;display:block}.sk-eq{width:100%}
.sk-sel h4{margin:0 0 6px;font:700 14px inherit;font-family:inherit;letter-spacing:2px}.sk-slots{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.sk-slots .ar{color:#9db3b9;font-style:normal}
.ss{position:relative;width:130px;height:96px;background:#0c151c;border:1px solid #2a424c;color:#fff;cursor:pointer;text-align:left;padding:4px}.ss.on{border-color:#ff7a2a;box-shadow:0 0 12px #ff7a2a88}.ss .ski{display:block;height:54px}.ss .ski img{width:100%;height:100%;object-fit:contain}.ss b{position:absolute;left:6px;bottom:3px;font-size:14px}.ss small{position:absolute;right:6px;bottom:4px;font-size:10px;color:#9db3b9;max-width:80px;text-align:right}
.sk-h{margin:8px 0 0;color:#8fa7ad;font-size:12px}

#rcv{position:fixed;left:50%;top:16px;transform:translateX(-50%);z-index:12;display:none;text-align:center;color:#fff;background:#06121abb;border:1px solid #ff7a2a;padding:6px 16px;font:600 20px Teko,sans-serif;letter-spacing:2px;pointer-events:none}#rcv span{color:#ff7a2a;margin-left:10px}#rcv small{display:block;font:500 12px Rajdhani,sans-serif;color:#9db3b9;letter-spacing:1px}
@media(max-width:900px){.sk-main{grid-template-columns:1fr}}

/* ---------- top of screen: match info bar ---------- */
#ob{opacity:0;pointer-events:none}
#tbar{position:absolute;top:10px;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:6px;pointer-events:none;max-width:94vw;z-index:2;font-family:Rajdhani,sans-serif}
#tbar:empty{display:none}
#tbar .tr{display:flex;align-items:stretch;filter:drop-shadow(0 6px 12px #000a)}
#tbar .tt{position:relative;display:flex;align-items:baseline;gap:10px;min-width:132px;padding:5px 22px 11px;background:linear-gradient(180deg,#0d1d27ee,#08141c);overflow:hidden}
#tbar .tt b{font:700 44px/1 Teko,Impact,sans-serif;letter-spacing:1px;color:#fff;text-shadow:0 0 14px currentColor}
#tbar .tt i{font:700 14px Rajdhani,sans-serif;font-style:normal;letter-spacing:3px;opacity:.85}
#tbar .tt u{position:absolute;left:0;bottom:0;height:4px;transition:width .4s;background:currentColor;box-shadow:0 0 10px currentColor}
#tbar .tt.a{color:#4f9bff;justify-content:flex-start;clip-path:polygon(0 0,100% 0,calc(100% - 16px) 100%,0 100%);border-left:4px solid #4f9bff;padding-right:30px}
#tbar .tt.b{color:#ff6a50;justify-content:flex-end;clip-path:polygon(16px 0,100% 0,100% 100%,0 100%);border-right:4px solid #ff6a50;padding-left:30px}
#tbar .tt.a b,#tbar .tt.b b{color:#fff}
#tbar .tm{display:flex;flex-direction:column;align-items:center;justify-content:center;min-width:76px;padding:2px 10px 8px;background:#050c11f2;border:1px solid #ffffff22;border-width:0 1px;color:#cfe0e3}
#tbar .tm small{font:600 11px Rajdhani,sans-serif;letter-spacing:3px;color:#7f9aa3}
#tbar .tm b{font:700 28px/1 Teko,sans-serif;color:#ffb454}
#tbar .tcs{display:flex;flex-wrap:wrap;justify-content:center;gap:6px}
#tbar .tc{padding:3px 14px;background:#0a161ecc;border:1px solid #ffffff1c;border-bottom:2px solid #3b5963;color:#cfe0e3;font:600 15px Rajdhani,sans-serif;letter-spacing:1.5px;text-transform:uppercase;backdrop-filter:blur(3px);clip-path:polygon(8px 0,100% 0,calc(100% - 8px) 100%,0 100%)}
#tbar .tc.big{font:700 24px/1.1 Teko,sans-serif;padding:2px 22px;border-bottom-color:#ffb454;color:#fff;letter-spacing:2px}
#tbar .tc.blue{border-bottom-color:#4f9bff;color:#bcdcff}#tbar .tc.red{border-bottom-color:#ff6a50;color:#ffd0c6}#tbar .tc.warn{border-bottom-color:#ffd24a;color:#ffd24a;animation:tcw .8s ease-in-out infinite alternate}
#tbar .tc.zn{display:flex;align-items:center;gap:8px;padding-left:8px}#tbar .tc.zn em{display:inline-grid;place-items:center;width:22px;height:22px;font:700 17px Teko,sans-serif;font-style:normal;background:#444c52;color:#fff;border-radius:3px}
#tbar .tc.zn.blue em{background:#2f6fd6}#tbar .tc.zn.red em{background:#c4432e}
#tbar .solo .tc:first-child{font:700 22px/1.1 Teko,sans-serif;letter-spacing:2px;color:#fff;border-bottom-color:#ffb454}
@keyframes tcw{from{background:#2a220acc}to{background:#4a3a0acc}}
body.touch #tbar{top:6px;transform:translateX(-50%) scale(.78);transform-origin:top center}

/* ---------- killstreak panel: ready streaks glow ---------- */
#kst{z-index:2}
.kt{position:relative;border-radius:2px}
.kt.rdy{background:linear-gradient(90deg,#0a141acc,#5a3a08ee);border-right-width:6px;animation:ktr 1s ease-in-out infinite alternate}
.kt.rdy b{text-shadow:0 0 10px #ffb454}
.kt.rdy i{color:#ffd88a;font-weight:700;letter-spacing:1px}
@keyframes ktr{from{box-shadow:0 0 6px #ffb45455,inset 0 0 0 1px #ffb45433}to{box-shadow:0 0 24px 4px #ffb454cc,inset 0 0 0 1px #ffb454aa}}

/* ---------- settings: controls rebinding ---------- */
#rbg h3{margin:16px 0 6px;font:700 20px Teko,sans-serif;letter-spacing:2px;color:#ffb454}
.rbr{display:flex;align-items:center;gap:8px;padding:3px 0;border-bottom:1px solid #ffffff10}.rbr span{flex:1;font:600 16px Rajdhani,sans-serif;color:#cfe0e3}
