#gmfx.g-vint{backdrop-filter:grayscale(1) contrast(1.18) brightness(.95);background:repeating-linear-gradient(90deg,transparent 0 97px,rgba(255,255,255,.07) 97px 98px),radial-gradient(ellipse,transparent 50%,rgba(0,0,0,.5));animation:vint .12s steps(2) infinite}
@keyframes vint{0%{background-position:0 0,0 0}50%{background-position:7px 0,0 0}}

/* ---------- zombies left: one plain white counter ---------- */
#zrem{position:absolute;top:12px;left:50%;transform:translateX(-50%);font:700 46px/1 Teko,Impact,sans-serif;letter-spacing:2px;color:#fff;text-shadow:0 2px 0 #0009,0 0 14px #000a;opacity:0;transition:opacity .25s;pointer-events:none;z-index:2;font-variant-numeric:tabular-nums}
#zrem.on{opacity:.95}#zrem.tk{animation:zrTick .22s ease-out}@keyframes zrTick{0%{transform:translateX(-50%) scale(1.28)}100%{transform:translateX(-50%) scale(1)}}

.zgain{position:fixed;transform:translate(-50%,0);font:700 30px/1 Teko,Impact,sans-serif;letter-spacing:1px;color:#ffe27a;text-shadow:0 2px 0 #000a,0 0 12px #ffb000;pointer-events:none;z-index:50;animation:zgainUp 1.05s cubic-bezier(.2,.8,.3,1) forwards}
@keyframes zgainUp{0%{opacity:0;transform:translate(-50%,6px) scale(.7)}15%{opacity:1;transform:translate(-50%,-6px) scale(1.25)}100%{opacity:0;transform:translate(-50%,-44px) scale(1)}}

/* ======================= CHEWABLES page (Zombies menu) ======================= */
.t-s{--t:#7fb4ff}.t-c{--t:#ff7ad9}.t-m{--t:#5fe39a}.t-r{--t:#ffb454}.t-u{--t:#c47bff}
.cw{--ch:10px;display:flex;flex-direction:column;gap:16px;font-family:Teko,Impact,sans-serif}
.cw small{font:600 13px/1.1 Teko,sans-serif;letter-spacing:.16em;text-transform:uppercase;color:var(--mu)}
.cw-hd{display:flex;justify-content:space-between;align-items:flex-end;gap:18px;padding-bottom:12px;border-bottom:2px solid #ffffff14;position:relative}
