.cw-hd h2{margin:0!important;font-size:60px!important;line-height:.9;letter-spacing:.04em;text-transform:uppercase;transform:skewX(-8deg);color:#fff}

.cw-pk h3{margin:0 0 8px;font:700 24px/1 Teko,sans-serif;letter-spacing:.1em;text-transform:uppercase;color:var(--am)}.cw-pk h3 small{margin-left:10px;letter-spacing:.06em;text-transform:none;font-size:15px;font-weight:500}
.cw-slots{display:grid;grid-template-columns:repeat(5,1fr);gap:10px}
.cw-s{--c:#7fb4ff;position:relative;display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto;column-gap:12px;align-items:center;text-align:left;padding:10px 12px;color:#fff;border:0;cursor:pointer;min-height:84px;
 background:linear-gradient(135deg,#ffffff12,#ffffff05 55%,#0000);clip-path:polygon(0 0,calc(100% - 14px) 0,100% 14px,100% 100%,14px 100%,0 calc(100% - 14px));transition:transform .14s var(--ease),background .14s}
.cw-s:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--t,#ffffff30)}
.cw-s .cw-ball{grid-row:1/3;width:58px;height:58px}.cw-s b{font:700 22px/1 Teko,sans-serif;letter-spacing:.04em;text-transform:uppercase;align-self:end}.cw-s small{align-self:start;margin-top:2px}
.cw-s em{position:absolute;right:16px;top:6px;font:700 15px Teko,sans-serif;font-style:normal;color:#ffffff40}
.cw-s.on:hover{transform:translateY(-3px);background:linear-gradient(135deg,color-mix(in srgb,var(--c) 28%,transparent),#ffffff06 60%,#0000)}
.cw-s:not(.on){opacity:.55;cursor:default}.cw-ball.empty{background:#ffffff0c!important;box-shadow:inset 0 0 0 2px #ffffff22!important;color:#ffffff55;font:700 30px Teko,sans-serif}
.cw-main{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:16px;align-items:start}
.cw-fl{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}
.cw-fl button{font:600 19px Teko,sans-serif;letter-spacing:.1em;text-transform:uppercase;padding:2px 14px;color:#b8c8cc;background:#ffffff0a;border:0;cursor:pointer;transform:skewX(-10deg);transition:.12s}
.cw-fl button:hover{color:#fff;background:#ffffff18}.cw-fl button.on{color:#14100a;background:var(--am);box-shadow:0 0 14px #ffb45466}
.cw-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:8px;max-height:min(52vh,560px);overflow:auto;padding:2px 6px 6px 2px;scrollbar-width:thin;scrollbar-color:#ffffff30 transparent}
.cw-t{--c:#7fb4ff;position:relative;display:grid;grid-template-columns:auto 1fr;grid-template-rows:auto auto;column-gap:10px;align-items:center;text-align:left;padding:9px 10px;color:#fff;border:0;cursor:pointer;
 background:linear-gradient(135deg,#ffffff0e,#ffffff03 70%);clip-path:polygon(0 0,calc(100% - 10px) 0,100% 10px,100% 100%,10px 100%,0 calc(100% - 10px));transition:transform .12s var(--ease),background .12s;animation:cwIn .35s var(--ease) both}
.cw-t:before{content:"";position:absolute;left:0;right:0;bottom:0;height:3px;background:var(--t)}
.cw-t .cw-ball{grid-row:1/3;width:46px;height:46px}.cw-t b{font:700 19px/1 Teko,sans-serif;letter-spacing:.03em;text-transform:uppercase;align-self:end;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cw-t small{align-self:start;font-size:12px}
.cw-t em{position:absolute;right:12px;top:5px;font:700 17px Teko,sans-serif;font-style:normal;color:#fff;text-shadow:0 1px 0 #000}.cw-t u{position:absolute;right:12px;bottom:7px;text-decoration:none;font:700 11px Teko,sans-serif;letter-spacing:.14em;color:#14100a;background:var(--am);padding:0 5px}
.cw-t:hover,.cw-t:focus-visible{transform:translateY(-2px);background:linear-gradient(135deg,color-mix(in srgb,var(--c) 26%,transparent),#ffffff06 75%);outline:none}
.cw-t:focus-visible{box-shadow:inset 0 0 0 2px var(--am)}.cw-t.sel{background:linear-gradient(135deg,color-mix(in srgb,var(--c) 34%,transparent),#ffffff0a 80%);box-shadow:inset 0 0 0 2px #ffffffcc}
.cw-t.lock{opacity:.5}.cw-t.lock .cw-ball{filter:grayscale(1) brightness(.7)}.cw-t.lock:hover{opacity:.8}
.cw-none{grid-column:1/-1;color:var(--mu);font:500 20px Teko,sans-serif;padding:24px 4px}
@keyframes cwIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
/* the gumball token: a glossy sphere with the gum's own icon stamped in it */
.cw-ball{--c:#7fb4ff;position:relative;display:grid;place-items:center;flex:none;width:64px;height:64px;border-radius:50%;color:#0b1014;background:var(--c);
 background:radial-gradient(circle at 31% 25%,#ffffffe8 0 6%,#ffffff55 7% 14%,#fff0 15%),radial-gradient(circle at 50% 58%,color-mix(in srgb,var(--c) 88%,#fff) 0,var(--c) 50%,color-mix(in srgb,var(--c) 42%,#000) 100%);
 box-shadow:inset -5px -7px 12px #0006,inset 3px 3px 8px #fff3,0 5px 16px color-mix(in srgb,var(--c) 38%,transparent),0 0 0 2px #000a}
.cw-ball .cw-ic{width:56%;height:56%;stroke:#0d1014;stroke-width:2.2;filter:drop-shadow(0 1px 0 #ffffff70)}
.cw-ball.sample{width:132px;height:132px;animation:cwBob 3.2s ease-in-out infinite}
@keyframes cwBob{0%,100%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(-8px) rotate(3deg)}}
.cw-dt{--c:#7fb4ff;position:sticky;top:0;display:flex;flex-direction:column;gap:6px;padding:16px 18px 18px;min-height:420px;background:linear-gradient(180deg,#ffffff10,#ffffff04);
 clip-path:polygon(0 0,calc(100% - 18px) 0,100% 18px,100% 100%,18px 100%,0 calc(100% - 18px));border-top:3px solid var(--t)}
.cw-dt:before{content:"";position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 18%,color-mix(in srgb,var(--c) 30%,transparent),transparent 58%)}
.cw-big{display:grid;place-items:center;padding:14px 0 6px;position:relative}.cw-tr{color:var(--t)!important;text-align:center;position:relative}
.cw-dt h3{margin:0;text-align:center;font:700 40px/.95 Teko,sans-serif;letter-spacing:.04em;text-transform:uppercase;color:#fff;position:relative}
.cw-dt p{margin:4px 0 0;font:500 20px/1.15 Teko,sans-serif;color:#cfdde0;text-align:center;position:relative;min-height:70px}
.cw-hv{display:flex;align-items:baseline;gap:10px;justify-content:center;position:relative}.cw-hv b{font:700 44px/1 Teko,sans-serif;color:#fff}.cw-hv span{font:500 16px Teko,sans-serif;color:var(--mu);letter-spacing:.04em}
.cw-eq{position:relative;margin-top:2px;font:700 26px Teko,sans-serif;letter-spacing:.1em;text-transform:uppercase;padding:6px 16px;color:#14100a;background:var(--am);border:0;cursor:pointer;clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,12px 100%,0 calc(100% - 12px));transition:filter .12s,transform .12s}
.cw-eq:hover:not(:disabled){filter:brightness(1.12);transform:translateY(-2px)}.cw-eq.on{background:#ffffff1c;color:#fff}.cw-eq:disabled{background:#ffffff14;color:#ffffff55;cursor:default}
.cw-msg{min-height:20px;text-align:center;font:600 17px Teko,sans-serif;color:var(--rd);position:relative}
.cw-info{margin-top:auto;padding-top:10px;border-top:1px solid #ffffff14;position:relative}.cw-info b{display:block;font:700 18px Teko,sans-serif;letter-spacing:.12em;text-transform:uppercase;color:var(--am)}.cw-info span{font:500 17px/1.1 Teko,sans-serif;color:var(--mu)}
@media(max-width:980px){.cw-main{grid-template-columns:1fr}.cw-dt{position:relative;min-height:0}.cw-slots{grid-template-columns:repeat(2,1fr)}.cw-hd h2{font-size:44px!important}.cw-grid{max-height:none}}
/* the reward banner when a run reaches every tenth round */
