#gumhud i .cw-ic{width:70%;height:70%;stroke:#0d1014;stroke-width:2.4}

/* ---- the gum prompt, the bubble splat and the new gum HUD ---- */
#gmask{position:fixed;left:50%;bottom:150px;transform:translate(-50%,24px);display:none;align-items:center;gap:16px;padding:12px 20px 12px 14px;z-index:60;pointer-events:none;color:#fff;font-family:Teko,Impact,sans-serif;
 background:linear-gradient(135deg,#0e161cf2,#0a1015f2);border-top:3px solid var(--t,#7fb4ff);clip-path:polygon(0 0,calc(100% - 14px) 0,100% 14px,100% 100%,14px 100%,0 calc(100% - 14px));opacity:0;transition:opacity .22s,transform .3s cubic-bezier(.2,1.3,.4,1)}
#gmask.on{display:flex;opacity:1;transform:translate(-50%,0)}#gmask .cw-ball{width:66px;height:66px;--c:inherit}
#gmask .gq small{display:block;font:600 14px Teko,sans-serif;letter-spacing:.2em;text-transform:uppercase;color:var(--t)}#gmask .gq b{display:block;font:700 34px/1 Teko,sans-serif;letter-spacing:.05em;text-transform:uppercase}#gmask .gq p{margin:2px 0 0;font:500 17px/1.1 Teko,sans-serif;color:#c4d2d6;max-width:300px}
#gmask .gk{display:grid;grid-template-columns:auto auto;gap:6px 10px;align-items:center;margin-left:8px;padding-left:16px;border-left:1px solid #ffffff22}
#gmask kbd{min-width:30px;text-align:center;font:700 20px Teko,sans-serif;padding:0 8px;color:#14100a;background:var(--am);clip-path:polygon(0 0,calc(100% - 5px) 0,100% 5px,100% 100%,5px 100%,0 calc(100% - 5px))}#gmask .gk span{font:600 20px Teko,sans-serif;letter-spacing:.1em;text-transform:uppercase}
#gmsplat{position:fixed;inset:0;pointer-events:none;z-index:6;opacity:0;--c:#ff7ad9;background:radial-gradient(circle at 32% 70%,color-mix(in srgb,var(--c) 60%,transparent) 0 9%,transparent 10%),radial-gradient(circle at 62% 62%,color-mix(in srgb,var(--c) 55%,transparent) 0 12%,transparent 13%),radial-gradient(circle at 50% 80%,color-mix(in srgb,var(--c) 58%,transparent) 0 15%,transparent 16%),radial-gradient(circle at 78% 78%,color-mix(in srgb,var(--c) 50%,transparent) 0 8%,transparent 9%),radial-gradient(circle at 20% 84%,color-mix(in srgb,var(--c) 50%,transparent) 0 7%,transparent 8%),radial-gradient(ellipse at 50% 100%,color-mix(in srgb,var(--c) 35%,transparent),transparent 65%)}
#gmsplat.on{animation:gmSplat 1.7s ease-out forwards}@keyframes gmSplat{0%{opacity:0;transform:scale(1.25)}12%{opacity:1;transform:scale(1)}65%{opacity:.85;transform:translateY(8px)}100%{opacity:0;transform:translateY(60px)}}
#gumhud{left:calc(50% + 250px)!important;bottom:28px!important;width:60px;height:60px;padding:0!important;gap:0!important;background:none!important;box-shadow:none!important;backdrop-filter:none!important;border-radius:50%!important;display:none;pointer-events:none}
#gumhud.on{display:block!important}#gumhud .gmr{position:absolute;left:-7px;top:-7px;width:74px;height:74px;transform:rotate(-90deg)}
#gumhud .gmr circle{fill:none;stroke-width:2.6}#gumhud .gmr .bg{stroke:#ffffff12}#gumhud .gmr .fg{stroke:var(--c);opacity:.34;stroke-linecap:round;transition:stroke-dashoffset .3s linear}
#gumhud i{position:absolute;inset:0;width:60px!important;height:60px!important;display:grid;place-items:center;border-radius:50%;background:radial-gradient(circle at 31% 25%,#ffffffd0 0 6%,#fff0 15%),radial-gradient(circle at 50% 58%,color-mix(in srgb,var(--c) 88%,#fff),var(--c) 50%,color-mix(in srgb,var(--c) 42%,#000));box-shadow:inset -4px -6px 10px #0006,0 4px 14px #0008,0 0 0 2px #000a,0 0 16px color-mix(in srgb,var(--c) 45%,transparent)!important}
#gumhud.run i{animation:gmRun .9s ease-in-out infinite}@keyframes gmRun{50%{transform:scale(1.07)}}
#gumhud em{position:absolute;right:-8px;bottom:-4px;font:700 15px Teko,sans-serif;font-style:normal;padding:0 6px;color:#14100a;background:var(--am)}
@media(max-width:900px){#gumhud{left:auto!important;right:18px;bottom:120px!important}#gmask{bottom:210px;flex-wrap:wrap;max-width:92vw}}

.cw-warn{display:flex;gap:12px;align-items:baseline;padding:8px 14px;border-left:4px solid var(--rd);background:#ff5a3a14;font-family:Teko,sans-serif}.cw-warn b{font-size:22px;letter-spacing:.1em;text-transform:uppercase;color:var(--rd)}.cw-warn span{font-size:18px;color:#cfdde0}

/* ---- the emote wheel ---- */
#emw{position:fixed;left:50%;top:50%;width:460px;height:460px;margin:-230px 0 0 -230px;z-index:70;pointer-events:none;display:none;font-family:Teko,Impact,sans-serif;color:#fff}
#emw.on{display:block;animation:emIn .16s cubic-bezier(.2,1.2,.4,1)}@keyframes emIn{from{opacity:0;transform:scale(.85)}to{opacity:1;transform:none}}
#emw .ring{position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle,#0a1015f2 0 34%,#0a101599 35% 100%);box-shadow:inset 0 0 0 2px #ffffff22,0 24px 70px #000a}
#emw .sl{position:absolute;left:50%;top:50%;width:104px;height:104px;margin:-52px 0 0 -52px;display:grid;place-items:center;align-content:center;gap:0;text-align:center;background:#ffffff0c;clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,12px 100%,0 calc(100% - 12px));transform:rotate(var(--a)) translateY(-170px) rotate(calc(var(--a) * -1));transition:background .1s,color .1s,scale .1s}
#emw .sl svg{width:42px;height:42px}#emw .sl b{font:700 20px/1 Teko,sans-serif;letter-spacing:.1em;text-transform:uppercase}#emw .sl em{position:absolute;right:9px;top:3px;font:600 13px Teko,sans-serif;font-style:normal;color:#ffffff55}
#emw .sl.on{background:var(--am);color:#14100a;scale:1.14;box-shadow:0 0 28px #ffb454aa}#emw .sl.on em{color:#14100a99}
#emw .ct{position:absolute;inset:0;display:grid;place-content:center;text-align:center}#emw .ct small{font:600 15px Teko,sans-serif;letter-spacing:.3em;color:var(--am)}#emw .ct b{font:700 40px/1 Teko,sans-serif;letter-spacing:.06em;text-transform:uppercase}

/* Multiplayer calling cards and emblem editor */
.idr-header {
 display:grid;
 grid-template-columns:minmax(0,1fr) minmax(155px,270px);
 align-items:center;
 gap:20px;
 padding-bottom:18px;
}
#idr-title {font:700 clamp(36px,4vw,56px)/.95 Teko,Impact,sans-serif;letter-spacing:.055em;text-transform:uppercase}
.idr-header .sub {margin:6px 0 0}
.idr-plate,.idr-art-frame {
 position:relative;
 isolation:isolate;
 display:flex;
 min-width:0;
 overflow:hidden;
 border:1px solid var(--idr-shade);
 border-left:2px solid var(--idr-ink);
 color:#f1f8f9;
 background:linear-gradient(96deg,#0c151e 15%,var(--idr-shade) 69%,#101b22 100%);
}
.idr-plate {align-items:center;gap:8px;width:min(100%,230px);min-height:40px;padding:4px 8px 4px 5px;vertical-align:middle}
#idr-equipped .idr-plate {width:100%;min-height:58px;padding:6px 10px 6px 8px;gap:11px}
.idr-card-art {position:absolute;z-index:-1;inset:0;width:100%;height:100%;color:var(--idr-ink);pointer-events:none}
.idr-plate .idr-card-art {opacity:.65;mask-image:linear-gradient(90deg,transparent 15%,#000 74%)}
.idr-plate-text {min-width:0;display:flex;flex-direction:column;line-height:1.1;text-shadow:0 1px 4px #020709,0 0 6px #000}
.idr-plate-text strong,.idr-plate-text small {overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
.idr-plate-text strong {font-size:15px;color:#f6fafb}
.idr-plate-text small {margin-top:2px;color:#e2edf0;font-size:11px;font-weight:600}
#idr-equipped .idr-plate-text strong {font-size:19px}
#idr-equipped .idr-plate-text small {font-size:13px}
.idr-badge {
 display:grid;
 place-items:center;
 flex:none;
 width:30px;
 aspect-ratio:1;
 overflow:hidden;
 padding:2px;
 border:1px solid #a5c3cc65;
 background:radial-gradient(circle at top,#30434c,#111c24);
}
#idr-equipped .idr-badge {width:44px}
.idr-mark {display:block;width:100%;height:auto;max-height:100%;pointer-events:none}
.idr-button {
 border:1px solid var(--idr-border);
 color:#d8e7e9;
 background:#12222a;
 padding:6px 11px;
 font:700 15px/1.2 Rajdhani,sans-serif;
 cursor:pointer;
}
.idr-button[aria-pressed="true"] {border-color:var(--am);color:#ffcb85;background:#30281d}
.idr-button:disabled {opacity:.43;cursor:default}
.idr-list-head {display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px}
#p-identity h3 {margin:0;color:#e6f1f2;font:600 24px/1 Teko,Impact,sans-serif;letter-spacing:.06em;text-transform:uppercase}
#p-identity h3 small {color:var(--mu);font:600 14px Rajdhani,sans-serif;letter-spacing:normal}
.idr-card-grid,.idr-emblem-grid {display:grid;grid-template-columns:repeat(auto-fill,minmax(min(100%,190px),1fr));gap:10px}
.idr-card-choice,.idr-emblem-choice {
 display:block;
 width:100%;
 min-width:0;
 padding:4px;
 border:1px solid var(--idr-border);
 background:#0e1b23;
 color:#edf4f5;
 font:inherit;
 text-align:left;
 cursor:pointer;
}
.idr-card-choice[aria-pressed="true"],.idr-emblem-choice[aria-pressed="true"] {border-color:var(--am);background:#29251e}
.idr-card-choice:disabled {cursor:default}
.idr-card-choice:disabled .idr-art-frame {filter:saturate(.66) brightness(.81)}
.idr-card-choice:not(:disabled):hover,.idr-emblem-choice:hover,.idr-button:not(:disabled):hover, .idr-button:focus-visible {border-color:var(--am);color:#fff}
.idr-art-frame {display:block;aspect-ratio:3.6;min-height:45px}
.idr-lock {position:absolute;top:4px;right:5px;padding:2px 6px;background:#0a141aee;color:#f7e1c4;font-size:12px;font-weight:700}
.idr-choice-caption {display:block;padding:6px 5px 3px}
.idr-choice-caption strong,.idr-emblem-choice strong {display:block;font-size:17px;line-height:1.15}
.idr-choice-caption small,.idr-emblem-choice small {display:block;color:#abc1c6;font-size:13px}
.idr-card-choice[aria-pressed="true"] small,.idr-emblem-choice[aria-pressed="true"] small {color:var(--am)}
.idr-emblem-grid {grid-template-columns:repeat(auto-fill,minmax(min(100%,136px),1fr))}
.idr-emblem-choice {display:grid;justify-items:center;gap:3px;padding:12px 5px 8px;text-align:center}
.idr-emblem-choice .idr-badge {width:66px;margin-bottom:5px;padding:6px}
.idr-editor {display:grid;grid-template-columns:minmax(142px,.8fr) minmax(216px,1.2fr);align-items:start;gap:14px}
.idr-editor-preview,.idr-editor-tools {min-width:0;padding:13px;border:1px solid var(--idr-border);background:var(--idr-panel)}
.idr-draft-art {
 display:grid;
 place-items:center;
 margin:10px auto;
 width:min(100%,240px);
 aspect-ratio:1;
 border:1px solid var(--idr-border);
 background:
  linear-gradient(0deg,transparent calc(50% - .5px),#69b8c350 50%,transparent calc(50% + .5px)),
  linear-gradient(90deg,transparent calc(50% - .5px),#69b8c350 50%,transparent calc(50% + .5px)),
  repeating-linear-gradient(0deg,transparent 0 19px,#34535d50 19px 20px),
  repeating-linear-gradient(90deg,transparent 0 19px,#34535d50 19px 20px),
  radial-gradient(ellipse,#1b2c36,#0a151c);
}
.idr-layer-list,.idr-editor-actions {display:flex;flex-wrap:wrap;gap:5px;margin:8px 0}
.idr-layer-list {padding:7px 0;border-block:1px solid var(--idr-border)}
.idr-editor-actions select {flex:1;min-width:75px;width:auto}
.idr-layer-fields {display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:2px 10px}
.idr-layer-fields label {margin:4px 0;color:#bfd0d3;font-weight:600}
.idr-layer-fields output {float:right;color:var(--am);font-variant-numeric:tabular-nums}
.idr-editor input[type="range"] {display:block;padding:3px 0;accent-color:var(--am)}
.idr-editor select {font:600 15px Rajdhani,sans-serif}
.idr-save {width:100%;margin-top:5px;background:var(--am);border-color:var(--am);color:#1b1408}
.idr-save:not(:disabled):hover {background:#ffd097;color:#1b1408}
#idr-swatch {display:inline-block;float:right;width:16px;height:12px;margin-top:4px;border:1px solid #536974}
#idr-status {min-height:1.4em;margin:7px 0 0;color:#a8ebcc}
.idr-ch-rewards {display:grid;gap:3px;margin:5px 0 2px;padding:0;list-style:none}
.idr-ch-rewards li {display:flex;flex-wrap:wrap;justify-content:space-between;gap:0 6px;padding:3px 6px;background:#17262c;color:#aec5cb;font-size:13px}
.idr-ch-rewards b {color:#f1ca91}
.idr-report-reward {display:block;color:#f1ca91;font-size:13px}
#plist:has(.idr-plate) {display:flex;flex-wrap:wrap;gap:6px 10px;padding:0;list-style:none}
#plist .idr-plate {width:182px}
#sbd {width:min(525px,calc(100% - 18px));min-width:0;max-height:85vh;overflow:auto}
#sbd th {text-align:left;color:var(--mu)}
#sbd th:nth-child(n+3),#sbd td:nth-child(n+3) {text-align:right}
#sbd td .idr-plate,#fbd td .idr-plate {min-height:32px;padding-block:2px}
#sbd td .idr-badge,#fbd td .idr-badge {width:26px}
.kc-top .idr-plate {width:100%;margin:4px 0 5px;text-align:left}
@media (max-width:600px) {
 .idr-header {grid-template-columns:1fr;gap:8px;padding-bottom:9px}
 #idr-equipped .idr-plate {max-width:270px;min-height:46px}
 #idr-equipped .idr-badge {width:34px}
 .idr-card-grid {grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}
 .idr-editor {grid-template-columns:1fr}
 .idr-draft-art {width:min(68%,200px)}
 #sbd {padding:9px 10px}
 #sbd td {padding:3px 4px}
}

/* Local two-player shell. */
body.split-shell {display:grid;grid-template-rows:29px minmax(0,1fr);height:100%;background:#050a0d}
#split-toolbar {display:flex;justify-content:space-between;align-items:center;gap:10px;padding:0 12px;color:#eaf4f6;letter-spacing:.075em;font-size:13px}
#split-toolbar button {cursor:pointer;border:1px solid #46616a;background:#192931;color:#eaf4f6;font:700 14px Rajdhani,sans-serif}
#split-layout {display:grid;grid-template:repeat(2,minmax(0,1fr))/minmax(0,1fr);gap:2px;min-height:0;overflow:hidden;background:#28434d}
#split-layout iframe {display:block;width:100%;height:100%;min-width:0;min-height:0;border:0;background:#071119}
@media (min-aspect-ratio: 5/2){
 #split-layout {grid-template:minmax(0,1fr)/repeat(2,minmax(0,1fr))}
}
body.split-seat #hud {z-index:1}
body.split-seat #eqhud{position:absolute;left:20px;top:180px;font-size:12px}
body.split-seat #eqhud .eq{display:flex;align-items:center;gap:5px}
body.split-seat #eqhud kbd{min-width:22px;text-align:center}
body.split-seat #hint {display:none}
body.split-seat #sbd {top:5%;max-height:94vh}
body.split-seat .kc-rec {width:min(245px,29vw);right:10px}
body.split-seat .kc-bot {bottom:10px}

/* Shared presentation for the front end and match overlays. */
#home,#menu,#pause,#end,#fbd,#sbd,.split-shell {
 --canvas:#101417;
 --surface:#181f24;
 --raised:#222c32;
 --signal:#a9c7c7;
 --line:#ffffff20;
 --bright-line:#ffffff41;
 --text:#f5f0e8;
 --soft:#b4afb0;
 --accent:#e9b887;
 --accent-dark:#241a12;
 --ink:var(--text);
 --mu:var(--soft);
 --am:var(--accent);
 --display:"Barlow Condensed","Arial Narrow",Impact,sans-serif;
 --ui:Inter,"Segoe UI",system-ui,sans-serif;
 --gutter:clamp(18px,3.6vw,64px);
 --curve:cubic-bezier(.22,.7,.25,1);
 color:var(--text);
 font:500 14px/1.5 var(--ui);
}
#menu.zm,body.zom #pause,body.zom #end,body.zom #sbd {
 --canvas:#131112;
 --surface:#1e191a;
 --raised:#292021;
 --signal:#c4aaaa;
 --accent:#f0a18c;
 --accent-dark:#2a1613;
}
#menu,#home { padding:0;background:var(--canvas); }
#menu { overflow:hidden;isolation:isolate; }
#menu::before {
 content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
 background:
  radial-gradient(ellipse at 78% -11%,#6da8b01f,transparent 49%),
  linear-gradient(143deg,transparent 79%,#ffffff07 79.07%,transparent 79.16%,transparent 84%,#ffffff07 84.07%,transparent 84.16%);
}
#menu.zm::before { background:radial-gradient(ellipse at 85% -5%,#a45f5226,transparent 48%); }
#menu [hidden] { display:none!important; }
#menu button,#home button { color:inherit; }
#menu ::-webkit-scrollbar-thumb { background:var(--bright-line);background-clip:padding-box; }
#menu select,#menu input[type=text],#pause select {
 appearance:auto;
 min-height:40px;
 padding:8px 10px;
 color:var(--text);background:var(--canvas);border:1px solid var(--bright-line);border-radius:5px;
 font:500 13px var(--ui);color-scheme:dark;
}
#menu input[type=range],#pause input[type=range] { background:none;border:0;accent-color:var(--accent); }
#home button:focus,#menu :focus,#pause :focus,#end :focus {
 outline:2px solid var(--accent);
 outline-offset:3px;
 box-shadow:none;
}
#menu h2,#home h2,#pause h2,#end #et,#fbd h2 {
 font:700 clamp(37px,4.5vw,62px)/.95 var(--display);
 letter-spacing:.012em;text-transform:uppercase;color:var(--text);
 margin:0;
}
#menu h3 { color:var(--text); }
#menu .sub { color:var(--soft);line-height:1.5;font-size:13px; }
#menu h3,#menu h4,#home h2 { margin:0; }
#menu h3 { font:600 21px/1.08 var(--display);letter-spacing:.02em;text-transform:uppercase; }
#menu progress {
 appearance:none;border:0;background:#ffffff16;border-radius:3px;overflow:hidden;accent-color:var(--accent);
}
#menu progress::-webkit-progress-bar { background:#ffffff16; }
#menu progress::-webkit-progress-value { background:var(--accent); }
#menu progress::-moz-progress-bar { background:var(--accent); }

.menu-header {
 display:grid;grid-template-columns:auto minmax(0,1fr) auto;
 align-items:center;gap:clamp(16px,3vw,54px);height:70px;
 position:absolute;z-index:3;inset:0 0 auto;padding:0 var(--gutter);
 background:linear-gradient(100deg,#172128,#0d1215 44%,#141b1f);border-bottom:1px solid #91c4c43b;
}
.wordmark { display:flex;align-items:center;gap:9px;white-space:nowrap; }
.wordmark svg { color:var(--accent);height:33px;width:33px;fill:none;stroke:currentColor;stroke-width:1.9;stroke-linejoin:round; }
.wordmark h1 { margin:0;font:700 25px/.95 var(--display);color:var(--text);letter-spacing:.025em;text-shadow:none; }
.wordmark h1 b { font-weight:600;color:var(--accent); }
#nav { display:flex;align-items:stretch;gap:clamp(2px,.65vw,12px);height:100%;min-width:0;overflow-x:auto;scrollbar-width:none; }
#nav [data-secondary],#menu.zm #nav .mp,#menu.mp #nav .zm { display:none; }
#nav button {
 flex:0 0 auto;position:relative;align-self:stretch;
 padding:0 clamp(8px,1.2vw,20px);border:0;background:transparent;color:var(--soft);
 font:750 11px/1 var(--ui);letter-spacing:.075em;text-transform:uppercase;cursor:pointer;white-space:nowrap;
 transition:color .15s,background-color .2s;
}
#nav button:hover,#nav button.on { color:var(--text);background:#ffffff08; }
#nav button.on { background:linear-gradient(0deg,#e9b8871b,transparent 78%); }
#menu.zm #nav button.on { background:linear-gradient(0deg,#f0a18c21,transparent 79%); }
#nav button.on::after { content:"";position:absolute;inset:auto 10px 0;height:2px;background:var(--accent); }
#nav button:focus { outline-offset:-4px; }
.menu-utility { display:flex;align-items:center;gap:7px; }
.utility-icon,.profile-open {
 display:flex;align-items:center;justify-content:center;gap:8px;
 border:1px solid transparent;border-radius:5px;background:transparent;
 min-width:38px;min-height:40px;font:600 13px var(--ui);cursor:pointer;
}
.utility-icon svg,.profile-open svg { width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round; }
.utility-icon:hover,.utility-icon.on,.profile-open:hover,.profile-open[aria-expanded=true] { background:var(--raised);border-color:var(--line); }
.profile-open { padding:4px 7px; }
.profile-open svg { width:14px;color:var(--soft); }
#profile-initial {
 display:grid;place-items:center;width:28px;height:28px;border-radius:3px;color:var(--accent);
 background:#ffffff10;border:1px solid #ffffff2c;font:700 15px var(--ui);
}
#profile-name { max-width:12ch;overflow:hidden;text-overflow:ellipsis;white-space:nowrap; }
#prof {
 position:absolute;right:var(--gutter);top:calc(100% + 8px);width:min(263px,calc(100vw - 38px));padding:16px;
 background:var(--surface);border:1px solid var(--bright-line);border-radius:8px;box-shadow:0 15px 42px #0009;
}
#rank { margin:14px 0 6px;color:var(--accent);font:600 13px var(--ui); }
#xpb { height:4px;background:var(--line);border-radius:3px;overflow:hidden; }
#xpf { width:0;height:100%;background:var(--accent);transition:width .3s; }
#menu main { position:absolute;inset:70px 0 0; }
#menu .pn {
 display:none;height:100%;overflow:auto;overscroll-behavior:contain;scrollbar-width:thin;
 padding:clamp(21px,3.4vh,42px) max(var(--gutter),calc((100% - 1472px)/2)) max(24px,env(safe-area-inset-bottom));
 background:none;border:0;clip-path:none;backdrop-filter:none;
}
#menu .pn.on { display:block; }
.panel-head { display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:21px; }
.panel-head .sub { margin:6px 0 0;max-width:55ch; }
.section-line { display:flex;align-items:center;justify-content:space-between;gap:12px;margin:24px 0 11px; }
.section-line>span { color:var(--soft);font-size:12px; }
.eyebrow,.mode-label {
 margin:0 0 8px;
