#menu button.big:disabled,#menu .studio-primary:disabled,#menu .cw-eq:disabled { background:var(--raised);border-color:var(--line);color:var(--soft);box-shadow:none;opacity:1; }
#menu .idr-button,#menu .btn.alt {
