#menu .idr-save,#menu .studio-primary { background:var(--accent);color:var(--accent-dark); }
#menu .segmented { display:flex;gap:3px;flex-wrap:wrap;margin-bottom:14px; }
#menu .segmented button,#menu .cw-fl button {
 min-height:38px;padding:7px 13px;
 color:var(--soft);border:1px solid transparent;border-radius:4px;background:transparent;
 font:650 12px/1.2 var(--ui);letter-spacing:0;text-transform:none;cursor:pointer;transform:none;box-shadow:none;
}
