/* Match selection and bot lobby. */
.setup-head,.setup-shell .section-line { margin-top:0; }
.setup-head { padding-bottom:15px;border-bottom:1px solid var(--line); }
.setup-shell {
 display:grid;grid-template-columns:minmax(280px,.78fr) minmax(0,1.75fr);
 align-items:start;gap:clamp(15px,2.4vw,34px);
}
.setup-shell .section-line { margin-bottom:11px; }
.setup-playlists,.setup-maps { min-width:0; }
.playlist-list,.setup-map-grid { display:grid;gap:6px; }
#menu .playlist-choice,#menu .map-choice { border-color:var(--line);border-radius:4px; }
#menu .playlist-choice {
 display:grid;grid-template-columns:29px minmax(0,1fr) 13px;gap:10px;align-items:center;
 min-height:43px;padding:5px 9px;background:linear-gradient(113deg,#ffffff07,transparent 79%),var(--surface);
}
#menu .playlist-choice b { font:650 13px/1.15 var(--ui); }
.playlist-choice small { display:block;margin-top:2px;color:var(--soft);font:500 10px/1.15 var(--ui); }
.playlist-mark {
 position:relative;width:27px;height:27px;border:1px solid var(--line);border-radius:3px;
 background:#ffffff09;color:var(--signal);
}
.playlist-mark::before,.playlist-mark::after { content:"";position:absolute;inset:7px;border:1px solid currentColor;transform:rotate(45deg); }
.playlist-mark::after { inset:11px;background:currentColor;border:0; }
.playlist-mark[data-kind=team]::before { inset:6px 12px 10px 5px;transform:none;border-style:solid;box-shadow:6px 5px 0 -1px var(--signal); }
.playlist-mark[data-kind=team]::after { display:none; }
.playlist-mark[data-kind=wave]::before { inset:8px 6px;border-width:1px 0;transform:skewY(-29deg); }
.playlist-mark[data-kind=wave]::after { inset:12px 6px;transform:skewY(-29deg); }
.playlist-mark[data-kind=shuffle]::before { inset:8px 6px;border-width:1px 0;transform:skewY(30deg); }
.playlist-mark[data-kind=shuffle]::after { inset:8px 6px;background:none;border-block:1px solid currentColor;transform:skewY(-30deg); }
.setup-check { width:12px;height:12px;border:1px solid #ffffff56;border-radius:50%; }
#menu .playlist-choice[aria-pressed=true],#menu .map-choice[aria-pressed=true] { border-color:var(--accent); }
#menu .playlist-choice[aria-pressed=true] {
 background:linear-gradient(90deg,#e9b88721,transparent 80%),var(--surface);
 box-shadow:inset 2px 0 var(--accent);
}
[aria-pressed=true]>.setup-check { background:var(--accent);border-color:var(--accent);box-shadow:inset 0 0 0 2px #24201d; }
#menu .playlist-choice:hover,#menu .map-choice:hover { border-color:var(--accent); }
.setup-rule {
 min-height:3.2em;margin:0 0 8px;padding:8px 11px;color:var(--soft);font-size:12px;
 border-inline-start:2px solid var(--accent);background:#ffffff06;
}
.setup-map,.queue-map {
 position:relative;display:grid;align-items:end;isolation:isolate;overflow:hidden;
 border:1px solid var(--bright-line);border-radius:6px;background:#192326;
}
.setup-map { min-height:clamp(235px,32vh,380px);margin-bottom:8px; }
.map-feature-image,.map-choice-art { position:absolute;inset:0;pointer-events:none;z-index:-2; }
.map-feature-image,.map-choice-art,.deploy-art,.map-thumb,.home-art {
 background:var(--map-shot,linear-gradient(133deg,#273434,#17232e 59%,#343332)) var(--map-frame,center)/cover no-repeat;
}
.setup-map::after,.queue-map::after {
 content:"";position:absolute;inset:0;z-index:-1;pointer-events:none;
 background:linear-gradient(0deg,#080d12fa,#080d1285 38%,transparent 76%);
}
[data-map-art="?"]>.map-feature-image,[data-map-art="?"]>.map-choice-art {
 background:
  repeating-linear-gradient(0deg,#d3f0f013 0 1px,transparent 1px 22px),
  repeating-linear-gradient(90deg,#d3f0f013 0 1px,transparent 1px 22px),
  radial-gradient(ellipse at 76% 26%,#4a626e,#202c34 45%,#141c21);
}
.map-feature-info { padding:clamp(13px,2.4vw,32px);min-width:0; }
#menu .map-feature-info h3 { font:700 clamp(37px,5.3vw,73px)/.88 var(--display);color:#fff8ee; }
.map-feature-info p { color:#eee3d6;margin:9px 0 0;font-size:clamp(11px,1.07vw,14px);max-width:55ch; }
.setup-map-grid { grid-template-columns:repeat(3,minmax(0,1fr)); }
#menu .map-choice {
 display:flex;isolation:isolate;align-items:end;justify-content:space-between;gap:4px;
 position:relative;overflow:hidden;min-height:clamp(61px,5.9vw,84px);padding:6px 8px;
 color:#fff4e9;background:#182128;
}
.map-choice::before {
 content:"";position:absolute;inset:0;z-index:-1;
 background:linear-gradient(0deg,#0a1015f5,#0a101551 63%,#0a101523);
}
.map-choice .setup-check { flex-shrink:0;margin-bottom:2px; }
#menu .map-choice[aria-pressed=true] { box-shadow:inset 0 -2px var(--accent); }
#menu .map-choice b { text-shadow:0 1px 6px #000;font-size:12px; }
.map-choice-art { transition:transform .24s var(--curve); }
.map-choice:hover>.map-choice-art { transform:scale(1.055); }
#menu .action-arrow { display:inline-flex;gap:16px; }
.action-arrow::after { content:"→";font-size:16px;font-weight:550;line-height:1; }
.action-arrow:disabled::after { content:none; }

#menu #p-queue { --signal:#99d1d2; }
.queue-layout {
 display:grid;grid-template-columns:minmax(300px,.9fr) minmax(0,1.1fr);
 gap:9px;min-height:clamp(460px,66vh,680px);
}
.queue-search {
 display:flex;flex-direction:column;justify-content:center;align-items:start;gap:15px;
 padding:clamp(18px,3.6vw,57px);min-width:0;
 border:1px solid var(--line);border-radius:7px;
 background:radial-gradient(ellipse at 14% 10%,#28414367,transparent 65%),var(--surface);
}
.queue-signal {
 width:140px;max-width:45vw;aspect-ratio:1;position:relative;overflow:hidden;border-radius:50%;
 border:1px solid #a8dee084;margin-bottom:5px;
 background:
  linear-gradient(90deg,transparent 49.65%,#a8dee044 49.65% 50.35%,transparent 50.35%),
  linear-gradient(0deg,transparent 49.65%,#a8dee044 49.65% 50.35%,transparent 50.35%),
  repeating-radial-gradient(circle,#a8dee04d 0 1px,transparent 1px 17%);
 color:var(--signal);
}
.queue-signal::before {
 content:"";position:absolute;inset:0;
 background:conic-gradient(from 0deg,transparent 65%,#80d8d215 80%,#b3ede566 99%,#d6fff9a0);
 animation:queue-sweep 1.85s linear infinite;
}
.queue-signal i {
 position:absolute;width:6px;height:6px;background:currentColor;border-radius:50%;box-shadow:0 0 10px currentColor;
 animation:queue-ping 1.36s ease-in-out infinite alternate;left:36%;top:23%;
}
.queue-signal i:nth-child(2) { left:73%;top:51%;animation-delay:.42s; }
.queue-signal i:nth-child(3) { left:26%;top:65%;animation-delay:.8s; }
.queue-signal span { position:absolute;inset:calc(50% - 3px);background:var(--signal);transform:rotate(45deg); }
@keyframes queue-sweep { to { transform:rotate(360deg); } }
@keyframes queue-ping { from { opacity:.28; } to { opacity:1; } }
#p-queue[data-phase="2"] .queue-signal { border-color:var(--accent);background:radial-gradient(circle,#e9b88722,transparent 74%);color:var(--accent); }
#p-queue[data-phase="2"] .queue-signal::before {
 content:"✓";display:grid;place-items:center;background:none;animation:none;font:600 54px/1 var(--ui);
}
#p-queue[data-phase="2"] .queue-signal i,#p-queue[data-phase="2"] .queue-signal span { display:none; }
.queue-status { min-height:clamp(155px,16vw,188px); }
#menu .queue-status h2 { font-size:clamp(44px,5.1vw,74px);max-width:12.2ch; }
.queue-status p { margin:9px 0 0;color:var(--soft); }
.queue-actions { display:flex;flex-wrap:wrap;gap:7px; }
.queue-steps {
 display:flex;align-items:center;gap:6px;margin:0 0 4px;padding:0;list-style:none;
 color:var(--soft);font-size:11px;letter-spacing:.02em;
}
.queue-steps li { display:flex;align-items:center;gap:5px; }
.queue-steps li:not(:last-child)::after { content:"";width:14px;height:1px;background:var(--line);margin:0 3px; }
.queue-steps li[aria-current=step] { color:var(--accent);font-weight:700; }
.queue-steps li.done { color:var(--signal); }
.queue-steps li.done::before { content:"✓";font-size:10px; }
.queue-map .map-feature-image { transition:transform .42s var(--curve); }
#p-queue[data-phase="2"] .map-feature-image { transform:scale(1.023); }

@media(max-width:1000px) {
