/* Main quest encounter strip uses the existing Zombies HUD hierarchy. */
#zmain[hidden] { display:none; }
#zmain {
 position:absolute;z-index:3;top:clamp(52px,10vh,88px);left:50%;transform:translateX(-50%);
 width:min(424px,68vw);padding:9px 16px 12px;pointer-events:none;
 color:#fdf3e9;background:linear-gradient(95deg,transparent,#120e17e8 13%,#120e17e8 87%,transparent);
}
#zmain header { display:flex;justify-content:space-between;align-items:baseline;gap:6px 16px;flex-wrap:wrap;margin-bottom:6px; }
#zmain strong { font:700 clamp(18px,3.3vw,26px)/1 "Barlow Condensed","Arial Narrow",sans-serif;letter-spacing:.045em;text-transform:uppercase; }
#zmain small { color:var(--boss-ink);font:700 12px/1.2 Rajdhani,sans-serif;letter-spacing:.085em;text-transform:uppercase; }
#zmain .zmain-track {
 height:8px;position:relative;overflow:hidden;background:#120e17;border:1px solid #f0cfb646;
 clip-path:polygon(0 0,100% 0,calc(100% - 7px) 100%,0 100%);
}
#zmain .zmain-track::after {
 content:"";position:absolute;inset:0;
 background:linear-gradient(90deg,transparent 31.7%,#120e17 31.7% 32.5%,transparent 32.5% 65.7%,#120e17 65.7% 66.5%,transparent 66.5%);
}
#zmain .zmain-track i { display:block;height:100%;background:var(--boss-ink);transition:width .14s linear; }
#zmain.warded .zmain-track i { background:repeating-linear-gradient(125deg,var(--boss-ink) 0 6px,#6d6277 6px 11px); }
#zcinema[hidden]{display:none}
#zcinema{position:absolute;inset:0;display:flex;align-items:flex-end;padding:0 clamp(24px,7vw,105px) clamp(56px,13vh,136px);z-index:12;pointer-events:none;background:linear-gradient(90deg,#070609cc 0%,#07060940 52%,transparent 80%)}
#zcinema::before,#zcinema::after{content:"";position:absolute;left:0;right:0;height:7vh;background:#070609;animation:zcinema-bars .36s ease-out both}
