#zcinema::after{bottom:0;transform-origin:bottom}
#zcinema>div{position:relative;display:grid;gap:7px;max-width:min(460px,90vw);padding:11px 16px;border-left:3px solid var(--chapter-ink);text-shadow:0 2px 16px #000;animation:zcinema-caption .48s ease-out both}
