/* Stormfront standalone UI. */
.sf-page {
 --sf-ink:#eff6f3;--sf-muted:#a8b8bf;--sf-line:#67818d55;--sf-accent:#99f2d8;
 margin:0;min-height:100dvh;color:var(--sf-ink);background:#141c2e;
 font:500 15px/1.45 "DM Sans",system-ui,sans-serif;overflow:hidden;
}
.sf-page *{box-sizing:border-box}
.sf-page [hidden]{display:none!important}
.sf-page h1,.sf-page h2,.sf-page h3,.sf-page p{margin:0}
.sf-page h1,.sf-page h2,.sf-page h3,.sf-brand strong{font-family:"Barlow Condensed","Arial Narrow",system-ui,sans-serif}
.sf-page h1{font-size:clamp(2.2rem,5vw,5rem);line-height:.92;letter-spacing:-.045em}
.sf-page h2{font-size:1.6rem;line-height:1.06}
.sf-page h3{font-size:1.03rem}
.sf-page button,.sf-page input,.sf-page select{
 font:650 .85rem/1.3 "DM Sans",system-ui,sans-serif;color:var(--sf-ink);
 border:1px solid var(--sf-line);background:#212f40;padding:.55rem .72rem;border-radius:5px;
}
.sf-page button{cursor:pointer}
.sf-page button:not(:disabled):is(:hover,:focus-visible),.sf-page button[aria-pressed="true"]{border-color:var(--sf-accent);background:#314954;color:#d1fff2}
.sf-page button:disabled{opacity:.44;cursor:default}
.sf-page :is(button,a,input,select):focus-visible{outline:2px solid #c8fff1;outline-offset:3px}
.sf-page button.sf-primary{background:#a1edd8;color:#11252b;border-color:#a1edd8}
.sf-page button.sf-primary:not(:disabled):is(:hover,:focus-visible){background:#ccfff3;color:#152b2d}
.sf-page a{color:var(--sf-accent)}
.sf-page #sf-stage,.sf-page #sf-root{position:fixed;inset:0}
.sf-page #sf-stage canvas{display:block;width:100%;height:100%;touch-action:none}
.sf-page #sf-stage.sf-underlay::after{
 content:"";position:absolute;inset:0;pointer-events:none;
 background:linear-gradient(87deg,#0d1928cd 0%,transparent 44%,transparent 62%,#101b2b83 100%),linear-gradient(0deg,#0c1421ed 0%,transparent 27%);
}
.sf-page #sf-root{z-index:1}
.sf-page .sf-boot{position:absolute;inset:auto 16px 24px;padding:12px}
.sf-hub{display:grid;grid-template-rows:auto minmax(0,1fr);min-height:0}
.sf-header{
 display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:clamp(12px,3vw,44px);
 padding:13px clamp(14px,3.3vw,50px);background:#111929eb;border-bottom:1px solid var(--sf-line);
}
.sf-header nav,.sf-row,.sf-tabs,.sf-zones{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.sf-header nav{justify-content:center}
.sf-header nav button{border-color:transparent;background:transparent}
.sf-header nav button[aria-current],.sf-zones button[aria-current]{border-color:#7fe6ca55;background:#18383a;color:var(--sf-accent)}
.sf-brand{display:flex;align-items:center;gap:8px;line-height:1.02;white-space:nowrap}
.sf-brand>span{color:var(--sf-accent);font-size:2.15rem;line-height:1}
.sf-brand strong{font-size:1.58rem;letter-spacing:.06em}
.sf-brand small,.sf-info small,.sf-label{display:block;font-size:.68rem;letter-spacing:.11em;color:#a4bdc6;font-weight:800}
.sf-brand small{font-size:.52rem;margin-top:3px}
.sf-info{padding:2px 9px 2px 0;white-space:nowrap}
.sf-info strong{display:block;font-size:1.08rem;color:#f3fbf8}
.sf-back{display:inline-block;font-size:.8rem;white-space:nowrap;text-decoration:none}
.sf-screen{overflow:auto;padding:clamp(14px,3vw,46px);min-height:0;position:relative}
.sf-screen>.sf-heading{margin-bottom:18px}
.sf-heading p,.sf-muted,.sf-panel p,.sf-brief p,.sf-room p,.sf-opening p{color:var(--sf-muted)}
.sf-heading p{margin-top:9px}
.sf-screen>.sf-tabs,.sf-screen>.sf-row{margin:12px 0}
.sf-play{min-height:100%;display:grid;grid-template-columns:minmax(0,1fr) minmax(300px,355px);gap:24px}
.sf-map{position:relative;min-height:510px;display:flex;flex-direction:column;isolation:isolate}
.sf-map .sf-heading,.sf-zones,.sf-mission-list{position:relative;z-index:2}
.sf-map .sf-heading h1{text-shadow:0 3px 25px #081621}
.sf-zones{margin:16px 0 0}
.sf-mission-list{display:flex;gap:5px;flex-wrap:wrap;margin-top:auto;padding-top:12px;align-items:flex-end}
.sf-mission-list button{font-size:.77rem;background:#192c38e8}
.sf-brief,.sf-panel,.sf-kit-panel{background:#111e2de8;border:1px solid var(--sf-line);border-radius:10px}
.sf-brief{align-self:center;display:grid;gap:12px;padding:20px;min-height:410px;box-shadow:0 20px 50px #070b1450}
.sf-brief>h2{font-size:2rem}
.sf-room{border-top:1px solid var(--sf-line);padding-top:10px;margin-top:4px;display:grid;gap:8px}
.sf-room input{min-width:0;width:145px;text-transform:uppercase}
.sf-room input::placeholder{text-transform:none}
.sf-card-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(245px,100%),1fr));gap:12px;margin-top:15px;align-items:start}
.sf-panel{display:grid;align-content:start;justify-items:start;gap:9px;padding:16px}
.sf-panel select{width:100%;min-width:0}
.sf-panel progress{width:100%;accent-color:var(--sf-accent)}
.sf-perks{display:flex;flex-wrap:wrap;gap:4px}
.sf-page .sf-perks button{font-size:.72rem;padding:.4rem}
.sf-page .sf-notice{margin-top:14px;color:#d7fff0;background:#122e37e8;border-left:3px solid #87ddcd;padding:9px 12px}
.sf-workshop{pointer-events:none;animation:sf-fade .36s ease-out}
.sf-workshop button{pointer-events:auto}
.sf-opening{position:absolute;inset:auto 0 0;display:flex;align-items:center;justify-content:center;gap:12px;flex-wrap:wrap;padding:28px 16px;background:linear-gradient(transparent,#120f18ed)}
.sf-opening .sf-heading h1{font-size:clamp(2rem,4vw,3.6rem)}
.sf-opening .sf-heading{margin-right:24px}
.sf-reveal,.sf-result{
 position:absolute;inset:0;display:grid;align-content:center;justify-items:center;gap:19px;text-align:center;padding:20px;
 background:radial-gradient(ellipse,#263949ee,#101725f4 78%);animation:sf-fade .45s ease-out;
}
.sf-loot-grid{display:flex;flex-wrap:wrap;justify-content:center;gap:10px}
.sf-page .sf-loot-card{
 align-content:center;display:grid;gap:14px;line-height:1.15;min-height:142px;max-width:170px;width:clamp(88px,16vw,160px);
 border:1px solid var(--loot);color:var(--loot);background:linear-gradient(146deg,#353d55,#171d30 70%);box-shadow:0 0 22px -9px var(--loot);font-size:clamp(.9rem,2vw,1.45rem);
}
.sf-loot-card small{font-size:.74rem;line-height:1.12}
.sf-page .sf-chest{display:grid;place-items:center;font-size:4.2rem;background:#243843;color:#b0fbe2;width:120px;height:99px;border:2px solid #71b8ae;border-radius:17px;box-shadow:0 0 48px -12px #83d9c6;transform:rotate(-5deg)}
.sf-field{pointer-events:none}
.sf-hud{position:absolute;inset:0;padding:clamp(9px,1.9vw,28px);display:flex;flex-direction:column;justify-content:space-between}
.sf-hud button,.sf-field-dialog{pointer-events:auto}
.sf-field-top,.sf-field-bottom{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}
.sf-objective,.sf-field-left,.sf-ammo,.sf-interact,.sf-goal,.sf-boss{
 background:#101b28cc;border:1px solid #8faac34a;border-radius:7px;padding:10px 12px;max-width:min(460px,70vw);box-shadow:0 4px 25px #08152240;
}
.sf-objective h1{font-size:clamp(1.5rem,3.5vw,2.9rem);margin:4px 0}
.sf-objective p{font-size:clamp(.73rem,1.4vw,1rem)}
.sf-objective b{color:#b5f5df;font-size:1.25rem;font-variant-numeric:tabular-nums}
.sf-mapbox{display:grid;justify-items:end;gap:5px}
.sf-minimap{display:block;width:clamp(86px,13vw,170px);height:auto;border:1px solid #8ca7aa69;border-radius:7px}
.sf-field-bottom{align-items:end}
.sf-field-left{max-width:320px}
.sf-materials{font-size:.76rem;line-height:1.3}
.sf-bars{margin-top:6px;display:grid;gap:4px}
.sf-bars>div{display:grid;grid-template-columns:1fr auto;align-items:center;gap:7px}
.sf-bars span{font-size:.64rem;color:#e8f8f4;white-space:nowrap}
.sf-page meter{height:11px;width:100%;display:block;border:0;min-width:60px;appearance:none}
.sf-page meter::-webkit-meter-bar{background:#273849;border:0;border-radius:3px}
.sf-page meter::-webkit-meter-optimum-value{background:#6cf1ce;border-radius:3px}
.sf-bars>div:first-child meter::-webkit-meter-optimum-value{background:#6aaff5}
.sf-boss meter::-webkit-meter-optimum-value{background:#cbe6a1}
.sf-field-center{text-align:center;align-self:end}
.sf-field-hint,.sf-kit{font-size:.74rem;text-shadow:0 1px 8px #000;background:#121c29b3;padding:3px 6px;border-radius:4px}
.sf-kit{color:#b8fee9;font-weight:800;font-size:.86rem}
.sf-kit:empty,.sf-field-notice:empty,.sf-interact:empty{display:none}
.sf-abilities{display:flex;justify-content:center;flex-wrap:wrap;gap:3px;margin-top:4px}
.sf-page .sf-abilities button{background:#1b2b3cd9;font-size:.68rem;padding:4px 5px}
.sf-ammo{font-size:.85rem;white-space:nowrap}
.sf-interact,.sf-field-notice,.sf-goal,.sf-boss{position:absolute;left:50%;transform:translateX(-50%);text-align:center}
.sf-interact{top:60%;padding:5px 12px;color:#d3fbec}
.sf-field-notice{top:18%;color:#e7fbf3;background:#0f1d2bc2;border-radius:5px;padding:5px 12px;text-shadow:0 2px 4px #10202c;max-width:60vw}
.sf-goal{top:10%;width:min(320px,36vw);padding:7px 10px}
.sf-boss{top:25%;width:min(385px,65vw);display:grid;gap:3px;color:#ebeafa}
.sf-markers{position:absolute;inset:0;overflow:hidden}
.sf-marker{position:absolute;transform:translate(-50%,-50%);border-radius:4px;padding:2px 6px;background:#0c1924c9;border:1px solid #7fbeda79;color:#dcfaff;font-size:.65rem;white-space:nowrap}
.sf-field-dialog{position:absolute;z-index:4;inset:0;background:#101928ab;display:grid;place-items:center;padding:16px}
.sf-field-dialog>.sf-panel,.sf-kit-panel{max-width:min(830px,100%);max-height:91dvh;overflow:auto;min-width:min(360px,100%);padding:18px}
.sf-kit-panel .sf-heading h1{font-size:2rem}
.sf-kit-panel>.sf-primary{margin-top:8px}
.sf-edit-grid{display:grid;grid-template-columns:repeat(var(--columns),1fr);gap:6px;width:100%;min-width:160px}
.sf-edit-grid button{min-height:47px}
.sf-touch{display:none}
@keyframes sf-fade{from{opacity:0}to{opacity:1}}
@media(max-width:920px){
 .sf-header{grid-template-columns:auto 1fr;gap:8px}
 .sf-header nav{grid-column:1/-1;grid-row:2;justify-content:flex-start}
 .sf-header>.sf-row{justify-content:flex-end}
 .sf-play{grid-template-columns:minmax(0,1fr) minmax(240px,310px);gap:10px}
 .sf-map{min-height:470px}
 .sf-brief{padding:14px}
}
@media(max-width:650px){
 .sf-header{padding:7px 10px}
 .sf-header nav{gap:3px}
 .sf-header nav button,.sf-page .sf-back{font-size:.68rem}
 .sf-brand strong{font-size:1.25rem}
 .sf-info{padding-right:2px}
 .sf-info small{font-size:.58rem}
 .sf-info strong{font-size:.9rem}
 .sf-play{grid-template-columns:1fr}
 .sf-map{min-height:320px}
 .sf-brief{min-height:0}
 .sf-field-left,.sf-ammo{padding:5px;max-width:125px;white-space:normal}
 .sf-hud button{font-size:.64rem}
 .sf-objective{padding:5px 7px;max-width:58vw}
 .sf-field-hint{display:none}
}
@media(pointer:coarse){
 .sf-touch{display:flex;position:absolute;justify-content:space-between;align-items:end;left:12px;right:12px;bottom:78px;pointer-events:none}
 .sf-touch-dpad{display:grid;grid-template-columns:repeat(3,38px);gap:3px}
 .sf-touch-dpad button:first-child{grid-column:2}
 .sf-touch-dpad button:nth-child(2){grid-column:1}
 .sf-touch-actions{display:grid;grid-template-columns:repeat(2,52px);gap:4px}
 .sf-touch button{touch-action:none;background:#192c3ca8;padding:8px 4px}
}
@media(prefers-reduced-motion:reduce){.sf-page *{animation:none!important;transition:none!important}}

/* AetherCorp field hardware uses stencilled ink, etched grids and bevel cuts. */
.sf-page {
 --sf-ink:#eeeade;--sf-muted:#a6a698;--sf-line:#a9af864d;--sf-accent:#d7fa74;
 --sf-metal:#171e20;--sf-black:#111719;--sf-brass:#a5a16b;--sf-orange:#e9a066;
 --sf-mono:"SFMono-Regular",Consolas,"Liberation Mono",monospace;
 --sf-cut:polygon(0 0,calc(100% - 13px) 0,100% 13px,100% 100%,13px 100%,0 calc(100% - 13px));
 color:var(--sf-ink);background:#101619;
}
.sf-page :is(h1,h2,h3),.sf-brand strong{font-family:"Arial Narrow","Barlow Condensed","Arial Black",system-ui,sans-serif}
.sf-page h1{letter-spacing:-.065em;font-weight:950}
.sf-page :is(.sf-label,.sf-info small,.sf-brand small,.sf-back,.sf-map-key){font-family:var(--sf-mono)}
.sf-page :is(button,input,select),.sf-page .sf-brief,.sf-page .sf-panel,.sf-page .sf-kit-panel,
.sf-page :is(.sf-objective,.sf-field-left,.sf-ammo,.sf-interact,.sf-goal,.sf-boss,.sf-marker,.sf-minimap,.sf-field-notice,.sf-notice){border-radius:0}
.sf-page button,.sf-page input,.sf-page select{background:#252d2f;color:var(--sf-ink)}
.sf-page button:not(:disabled):is(:hover,:focus-visible),.sf-page button[aria-pressed="true"]{background:#38432b;color:#e9ffd1}
.sf-page button.sf-primary{
 background:var(--sf-accent);color:#161e12;border:0;clip-path:polygon(0 0,calc(100% - 8px) 0,100% 8px,100% 100%,0 100%);
 font-family:var(--sf-mono);font-weight:900;padding:.64rem .83rem;text-transform:uppercase;font-size:.77rem;
}
.sf-page button.sf-primary:not(:disabled):is(:hover,:focus-visible){background:#ecffad;color:#161e12}
.sf-page .sf-back{text-decoration:underline;text-underline-offset:3px;text-decoration-color:#d7fa7459}
.sf-page #sf-stage.sf-underlay::after{
 background:linear-gradient(88deg,#101619f5 0%,#10161913 43%,transparent 64%,#101619b0 100%),linear-gradient(0deg,#101619 0%,transparent 24%);
}
.sf-header{
 padding-block:11px;background:#101619f0;border-bottom:1px solid #cdd79b62;position:relative;
}
.sf-header::after{
 content:"";position:absolute;bottom:-4px;left:0;right:0;height:3px;background:linear-gradient(90deg,#dcfa7a 0 12%,transparent 12%);
 pointer-events:none;
}
.sf-brand>span.sf-crest{
 background:var(--sf-accent);width:26px;height:26px;
 clip-path:polygon(50% 0,100% 21%,84% 83%,50% 100%,16% 83%,0 21%,50% 0,50% 22%,21% 33%,30% 68%,50% 80%,70% 68%,79% 33%,50% 22%);
}
.sf-brand strong{letter-spacing:.035em;font-weight:950;font-size:1.36rem}
.sf-brand small,.sf-info small,.sf-label{color:#c1c1a1;letter-spacing:.08em}
.sf-header nav button{
 font:700 .75rem/1.15 var(--sf-mono);text-transform:uppercase;
 border:0;padding:.8rem .74rem;border-bottom:2px solid transparent;
}
.sf-header nav button[aria-current]{border-color:var(--sf-accent);background:#282f1f;color:var(--sf-accent)}
.sf-zones{gap:0;max-width:max-content;border-block:1px solid var(--sf-line)}
.sf-zones button{
 border:0;border-right:1px solid var(--sf-line);background:#151d21bd;font:750 .71rem/1.2 var(--sf-mono);text-transform:uppercase;padding:.62rem .55rem;
}
.sf-zones button[aria-current]{border-right-color:var(--sf-line);background:#d3ef80;color:#1d2716}
.sf-map .sf-heading h1{font-size:clamp(3rem,8.6vw,8.1rem);line-height:.89;text-transform:uppercase;color:#e7edd3}
.sf-map .sf-heading p{color:#c5c8ad;font:.8rem var(--sf-mono);text-transform:uppercase;text-shadow:0 2px 6px #151c1a}
.sf-map-key{
 display:flex;flex-wrap:wrap;gap:12px 17px;margin-top:auto;padding-top:12px;font-size:.68rem;color:#d0d5bc;text-transform:uppercase;
}
.sf-map-key span::before{content:"";display:inline-block;width:10px;height:9px;background:#749466;clip-path:polygon(25% 0,75% 0,100% 50%,75% 100%,25% 100%,0 50%);margin-right:6px}
.sf-map-key span:nth-child(2)::before{background:#8a719f}
.sf-map-key span:nth-child(3)::before{background:var(--sf-accent)}
.sf-mission-list{margin-top:8px;padding-top:6px}
.sf-brief,.sf-panel,.sf-kit-panel{
 position:relative;isolation:isolate;clip-path:var(--sf-cut);border:0;
 background:#827f64;padding:17px;box-shadow:none;
}
.sf-brief::before,.sf-panel::before,.sf-kit-panel::before{
 content:"";position:absolute;inset:1px;z-index:-1;clip-path:var(--sf-cut);
 background:linear-gradient(145deg,#252d2d,#141d20 73%);
}
.sf-brief::before{
 background:repeating-linear-gradient(150deg,#c9c6a702 0 4px,#060b0c10 4px 5px),linear-gradient(160deg,#2d382d,#151d21 73%);
}
.sf-brief{padding:24px 20px;gap:13px}
.sf-brief>h2{font-size:clamp(1.5rem,3vw,2.55rem);font-weight:950;color:#e6f8b9;text-transform:uppercase;letter-spacing:-.035em}
.sf-brief>small{color:#a8bb71}
.sf-brief>.sf-row:nth-of-type(1),.sf-brief>.sf-row:nth-of-type(2){
 display:grid;grid-template-columns:1fr 1fr;align-items:start;border-left:2px solid #b0c57560;padding-left:9px;gap:8px;
}
.sf-brief .sf-info{white-space:normal}
.sf-panel h2{font-size:1.17rem;text-transform:uppercase;font-weight:850;color:#e9ecd0}
.sf-panel .sf-label{color:#c9d49b}
.sf-screen>.sf-heading h1{color:#e3ebc3;text-transform:uppercase}
.sf-tabs button{background:#181f22;font-family:var(--sf-mono);text-transform:uppercase;font-size:.72rem}
.sf-tabs button[aria-pressed=true]{border-bottom:3px solid var(--sf-accent)}
.sf-room{padding-top:12px}
.sf-room h3{text-transform:uppercase;font-size:.88rem;letter-spacing:.025em;color:#dcdfc1}
.sf-opening .sf-heading h1,.sf-reveal .sf-heading h1,.sf-result .sf-heading h1{text-transform:uppercase}
.sf-opening{background:linear-gradient(transparent,#110e0df4)}
.sf-loot-card{clip-path:var(--sf-cut)}
.sf-reveal,.sf-result{
 background:repeating-linear-gradient(146deg,#bfce9d08 0 1px,transparent 1px 6px),radial-gradient(ellipse,#323728f2,#14191bf8 76%);
}
.sf-page .sf-chest{border-radius:0;clip-path:var(--sf-cut);background:#313b25;color:#e1f49f;box-shadow:none}
.sf-page .sf-marker{font-family:var(--sf-mono);color:#eaffc8;background:#172225d9;border-color:#c2d28764}
.sf-page :is(.sf-objective,.sf-field-left,.sf-ammo,.sf-interact,.sf-goal,.sf-boss){background:#151e24dc;border-color:#bfc6a659;box-shadow:none}
.sf-objective h1{text-transform:uppercase}
.sf-page .sf-abilities button,.sf-page .sf-field-hint,.sf-page .sf-kit{border-radius:0;background:#151d23df}
.sf-page .sf-minimap{border:1px solid #a6b192aa}
@media(max-width:650px){
 .sf-map .sf-heading h1{font-size:clamp(2.85rem,12vw,5.8rem)}
 .sf-header nav button{padding:.55rem .38rem}
 .sf-brief{padding:16px}
}
@media(min-width:1000px){
 .sf-screen:is([data-display="hero"],[data-display="weapon"])>.sf-card-grid{width:min(64%,920px);grid-template-columns:repeat(2,minmax(0,1fr))}
 .sf-screen:is([data-display="hero"],[data-display="weapon"])>.sf-heading{max-width:64%}
}
@media(prefers-reduced-motion:reduce){
 .sf-page .sf-reveal,.sf-page .sf-result{animation:none}
}

/* Homebase drafting glass, matte enamel and warm paper readouts. */
.sf-page {
 --sf-ink:#f0f9f6;--sf-muted:#c2d3d0;--sf-accent:#5ce1c6;--sf-line:#96e5d37d;
 --sf-matte:#28767e;--sf-glass:#184247df;--sf-amber:#f2a544;--sf-charcoal:#1e1c1a;
 --sf-cut:polygon(0 0,100% 0,100% 100%,0 100%);
 background:#111b1f;
}
.sf-page button,.sf-page input,.sf-page select{background:#15353ad9}
.sf-page button:not(:disabled):is(:hover,:focus-visible),.sf-page button[aria-pressed=true]{background:#27666a;color:#f0fffc;border-color:#82f3d6}
.sf-page button.sf-primary{background:var(--sf-amber);color:#291b11;clip-path:none;border:1px solid #fbd098}
.sf-page button.sf-primary:not(:disabled):is(:hover,:focus-visible){background:#ffc06b;color:#24170e}
.sf-page .sf-primary[aria-label*="Confirm"]{background:#8cd38b}
.sf-header{background:#0f171ceb;border-bottom:1px solid #59d8c4}
.sf-header::after{display:none}
.sf-brand strong,.sf-header nav button,.sf-page h1,.sf-page h2{font-stretch:condensed;font-weight:900;text-shadow:1px 2px #071314}
.sf-brand strong{letter-spacing:.065em;color:#fff}
.sf-header nav{gap:0}
.sf-header nav button{border-right:1px solid #739d9766;border-bottom:0;color:#f1f6ee}
.sf-header nav button:first-child{border-left:1px solid #739d9766}
