/* Jovian Terminus */
.tb[data-b="field"][hidden]{display:none}
[data-map-art="Jovian Terminus"]{--map-shot:url("data:image/webp;base64,")}
#jupiter-intro[hidden],#jupiter-intro [hidden]{display:none}
#jupiter-intro{--skip:0;--blackout:0;position:absolute;inset:0;z-index:15;color:#fff;pointer-events:none;background:rgb(0 0 0 / var(--blackout));box-shadow:inset 0 6.5vh #05080d,inset 0 -6.5vh #05080d}
