#jupiter-quest .jupiter-objective,#jupiter-quest .jupiter-log{border-left:2px solid #a69b82;padding:9px 13px;color:#eaf6ff;background:linear-gradient(90deg,#171813ec,#1718139f 83%,transparent)}
