#jupiter-waypoint.route-airlock{--wp:#cdb082}
#jupiter-waypoint i{display:block;width:12px;height:12px;margin:0 auto 7px;border:2px solid currentColor;background:#25251ed9;transform:rotate(45deg);box-shadow:0 0 9px #171711}
#jupiter-waypoint b{display:none;width:16px;height:17px;margin:0 auto 7px;background:currentColor;clip-path:polygon(50% 0,100% 100%,50% 73%,0 100%);transform:rotate(var(--heading))}
#jupiter-waypoint.route-edge i{display:none}
