#jupiter-waypoint span{display:block;max-width:min(210px,32vw);overflow:hidden;text-overflow:ellipsis;padding:3px 7px;background:#1d1c17df;border-radius:4px;font:700 clamp(10px,1.3vw,14px)/1.08 system-ui,sans-serif;letter-spacing:.015em}

#jupiter-quest strong,#jupiter-quest span{display:block}
#jupiter-quest strong{font:800 clamp(16px,2.1vw,23px)/1.05 "Barlow Condensed",sans-serif;letter-spacing:.055em;text-transform:uppercase;color:#e1d6be}
#jupiter-quest .jupiter-calibration{position:relative;height:9px;margin:8px 2px 1px;border:1px solid #716d59;background:linear-gradient(90deg,#292a24 var(--band-start),#74a79f var(--band-start) var(--band-end),#292a24 var(--band-end))}
#jupiter-quest .jupiter-calibration i{position:absolute;left:var(--cursor);height:12px;width:3px;top:-2px;background:#dac59a}
#jupiter-quest .jupiter-calibration.jupiter-in-band i{background:#f0e4c9;box-shadow:0 0 7px #cfc6a680}
#jupiter-quest .jupiter-log strong{color:#d9c9a8;font-size:16px}
#jupiter-quest span{font-size:clamp(11px,1.25vw,14px);line-height:1.3;margin-top:4px;text-shadow:0 1px 4px #000}
@media(max-width:650px){#jupiter-quest{left:8px;width:min(220px,52vw);top:74px}#jupiter-quest .jupiter-objective,#jupiter-quest .jupiter-log{padding:6px 8px}}

.jupiter-location{position:absolute;left:clamp(24px,6vw,76px);top:12vh;padding:.6em .85em;background:#0a141edb;border-left:2px solid #af9b75;color:#e0d4ba;font:700 clamp(14px,2vw,20px)/1 "Barlow Condensed",system-ui,sans-serif;letter-spacing:.13em;text-transform:uppercase}
.jupiter-dialogue{position:absolute;left:50%;bottom:13.5vh;transform:translateX(-50%);margin:0;width:max-content;max-width:83vw;padding:.52em .85em;background:#05080de8;text-align:center;font:720 clamp(17px,3vw,31px)/1.16 "Barlow Condensed",system-ui,sans-serif;letter-spacing:.035em}
.jupiter-skip{position:absolute;right:clamp(16px,4vw,56px);bottom:8.3vh;display:grid;gap:7px;padding:.6em .8em;border:1px solid #8f846d;background:#211e17e9;color:#e9f7ff;font:650 13px/1.2 system-ui,sans-serif;pointer-events:auto;touch-action:none}
.jupiter-skip i{height:3px;background:#6b6250}
