  radial-gradient(circle at 16px calc(100% - 16px),#9c9581 0 1.5px,#171712 2.5px 4px,transparent 4.5px),
  radial-gradient(circle at calc(100% - 16px) calc(100% - 16px),#9c9581 0 1.5px,#171712 2.5px 4px,transparent 4.5px),
  repeating-linear-gradient(173deg,#ffffff05 0 1px,transparent 1px 3px),linear-gradient(135deg,#3c3a2f,#23231e 74%);
 box-shadow:0 20px 70px #000b,inset 0 0 0 5px #171713,inset 0 0 0 7px #5c594b,inset 0 0 26px #1118;
